window.HB_TR["revelation"]["ks"]=["1. عیسیٰ مسیح سُند الہام، یُس خداین أمس دِژمُت چُھ، یُس پننین بندن تِم چیز ہاونہٕ خٲطرٕ یُس جلدٕے سپدُن۔ تہٕ تٔمۍ سوزُن تہٕ کوٚرُن پننِس فرشتہٕ سٍتـ̡ پننِس خادم یوحنا سٍتـ̡ اشارٕ:\n2. یُس خدایہِ سٕندِ کلامُک تہٕ عیسیٰ مسیح سٕنزِ گوٲہی ہُند تہٕ تٔمِس سارِنٕے چیزن ہُند یُس تٔمۍ وُچھمُت چُھ۔\n3. بابرکت چُھہ سُہ یُس پران چُھ، تہٕ یُس اتھ پیشن گویی ہٕندِ کلام بوزان چُھ، تہٕ تِم چیز تھاوان یِم اتھ منز لیکھنہٕ آمٕتۍ چِھ، تکیازِ وقتُک {چُھ} اتھس منز۔\n4. یوحنا سَتھ گرجا گھرن یُس ایشیاہس مَنٛز چُھ: فضل تہٕ امن، تٔمِس سٍتـ̡ یُس چُھ، تہٕ یُس چُھ، تہٕ یُس یُس یِنہٕ وول چُھ؛ تہٕ سَتھ روحو منزٕ یِم تٔمۍ سٕندِس تختس برونہہ کُن چھِ؛\n5. تہٕ عیسیٰ مسیح سٕندِ طرفہٕ، یُس وفادار گواہ چُھ، {تہٕ} مُردن ہُند گۄڈنیُک زامُت، تہٕ زمینہٕ کِس بادشاہن ہُند شہزادٕ چُھ۔ تٔمِس سٍتـ̡ یُس اسہِ محبت کٔرِتھ، تہٕ پننِس خونس سٍتـ̡ سانہِ گۅنہٕ نِش واش کٔرِتھ،\n6. تہٕ بنووُن اسہِ خدایہ تہٕ تٔمۍ سٕندِس مٲلِس خٲطرٕ بادشاہ تہٕ پادٕر۔ تٔمِس سٍتـ̡ روزُن جلال تہٕ غلبہٕ ہمیشہٕ خٲطرٕ۔ آمین۔\n7. وچھ سُہ چُھ اوٚبرٕ ہیتھ یوان۔ تہٕ پرٮ۪تھ أچھ آسہِ أمِس وُچھان، تہٕ تِمو تہِ یِمو أمِس زَد کٔرِتھ، تہٕ زمینہٕ ہٕندِس سارِنٕے رِشتہٕ کٔرِن أمِس سٍتـ̡ وُچھان۔ توتہِ چھہ آمین۔\n8. بہٕ چُھس الفا تہٕ اومیگا، آغاز تہٕ اختتام، خداوند چُھ ونان، یُس چُھ، تہٕ یُس اوس، تہٕ یُس یِنہٕ وول چُھ، قادر مطلق۔\n9. بہٕ یوحنا، یُس تُہند بوے تہٕ مصیبتس مَنٛز سٲتھی چُھ، تہٕ عیسیٰ مسیح سٕنزِ بادشاہی تہٕ صبرس مَنٛز، اوس تتھ جزیرس مَنٛز یتھ پتموس ونان چُھ، خدا سٕندِ کلامٕ خٲطرٕ، تہٕ عیسیٰ مسیح سٕنزِ گوٲہی خٲطرٕ۔\n10. بہٕ اوسُس خداوند سٕندِ دۅہہٕ روحس منز، تہٕ بوز پانس پَتہٕ اکھ بٔڈ آواز، یُس بُزرگ ہُند پٲٹھۍ،\n11.\\tیہ ونِتھ زِ بہٕ چُھس الفا تہٕ اومیگا، گۄڈنیُک تہٕ ٲخری تہٕ یُس ژے وُچھان چھُ، کُنہِ کتابہِ مَنٛز لیکھِو، تہٕ سوزُن سَتن گرجا گھرن یِم ایشیاہَس مَنٛز چھِ۔ ایفیسس تام، تہٕ سمیرنا تام، تہٕ پرگاموسس تام، تہٕ تھیاٹیرا تام، تہٕ سارڈس تام، تہٕ فلاڈیلفیا تام، تہٕ لاوڈیکیا تام۔\n12. تہٕ بہٕ پھیُر سُہ آواز وُچھان یُس میہ سٍتۍ کتھ کران اوس۔ تہٕ پھیرِتھ وُچھ میہ ستھ سۅنہٕ شمع۔\n13.\\tتہٕ ستن شمعدان منز، یُس انسان سٕندِس فرزندس ہٕندۍ پٲٹھۍ، کھورِ تام پلو لٲگِتھ تہٕ سۅنہٕ سٕندِس کمرس سٍتـ̡ گٔنڈِتھ۔\n14.\\tتٔمۍ سُند کلہٕ تہٕ تٔمۍ سٕندِس مَس اوس ییرٕکۍ پٲٹھۍ سفید، شینہٕ ہیوٗ سفید۔ تہٕ تٔمۍ سٕنٛزٕ أچھ ٲس نارٕچ نار ہٕندۍ پٲٹھۍ۔\n15.\\tتہٕ تٔمۍ سٕندِ کھۅر چِھہ باریک پیتل ہٕندۍ پٲٹھۍ، زن تِم بھٹس مَنٛز دزان۔ تہٕ تٔمۍ سٕنٛز آواز ٲس واریہن آبن ہٕنٛز آواز۔\n16.\\tتہٕ أمِس دچھنہِ اتھس منز ٲسۍ ستھ ستارہٕ: تہٕ أمِس ٲس دٔچھنِس اتھس منز اکھ تیز تلوار دراو تہٕ تٔمۍ سُند بُتھ اوس آفتاب سٕندِس طاقتس منز چمکان۔\n17.\\tتہٕ ییلہ میہ تس وُچھ، بہٕ پیوٚو تٔمۍ سٕندِس قدمن پیٹھ۔ تہٕ تٔمۍ تھوو میٲنس پیٹھ پنُن دٔچھُن اتھٕ تہٕ وونُن، خوفہٕ نہٕ کرُن۔ بہٕ چُھس گۄڈنیُک تہٕ ٲخری :\n18. بہٕ چُھس سُہ زندٕ تہٕ موٗدمُت۔ تہٕ وچھ بہٕ چُھس ہمیشہ زندٕ، آمین۔ تہٕ جہنمٕچ تہٕ موتٕچ کُنز۔\n19.\\tتِم چیز لیکھِو یُس ژے وُچھمُت چُھ، تہٕ یِم چیز یِم پَتہٕ یِنہٕ وٲلۍ۔\n20. سَتن ستارن ہُند اسرار یُس ژے میانہِ دچھنہِ اتھس منز وُچھمُت چھُ، تہٕ سَتھ سنہٕ سنہٕ شمعدان ۔ ستھ ستارٕ چِھ ستن گرجا گھرن ہٕندِ فرشتہٕ: تہٕ ستھ شمعدان یم ژے وُچھان چِھ، تم چِھ ستھ گرجا گھر۔","1. کلیساہٕ کِس فرشتہٕ سٍتـ̡ لیکھِو؛ یِم کتھٕ چھِ سُہ ونان یُس سَتھ تارٕ پننِس دٔچھنِس اتھس مَنٛز رٔٹِتھ چُھ، یُس سَتَن سنہٕ سنہٕ شمعَن مَنٛز پکان چُھ۔\n2. بہٕ چُھس چانہِ کامہِ، تہٕ تُہٕنزِ محنت، تہٕ تُہٕندِس صبرس پتاہ تہٕ ژے کِتھہ کٔنۍ ہیوٚک نہٕ تِم بد کار برداشت کٔرِتھ، تہٕ ژے چھُکھ تِمن آزماونہٕ آمُت یِم ونان چھِ زِ تِم چھِ رسول، تہٕ چُھنہٕ تِم اپُز لبنہٕ آمٕتۍ۔\n3. تہٕ کٔرٕن برداش، تہٕ صبر، تہٕ میانہِ ناوٕ خٲطرٕ کٔر محنتہٕ، تہٕ گٔیہٕ نہٕ بیہوش۔\n4. بہرحال، میہ چھہ ژے خلاف {کنہِ حدس تام}، تکیازِ ژے چھہ پنُن گۅڈنیُک عشق ترٲومُت۔\n5. تێمہِ کِنۍ کرو یاد تھاوُن تہٕ توبہ کٔرِو تہٕ گۅڈنِچ کٲم کٔرِو۔ نتہٕ بہٕ یِیہٕ جلدی ژےٚ نِش، تہٕ تُہند شمع تُلنہٕ پننہِ جایہِ پیٹھ، یوٚت تام ژٕ توبہ کرِ۔\n6.\\tمگر یہ چھہ ژیہ نیکولایتن ہٕندِس اعمالس سٍتۍ نفرت کران، یُس میہ تہِ نفرت کران چھُ۔\n7. یُس کَن چُھ، سُہ بوزُن یُس روح کلیسا سٍتـ̡ ونان چُھ۔ یُس فتح کرِ، تس دِیہٕ بہٕ زندگی ہٕندِس کُلِس کھٮ۪نہٕ خٲطرٕ، یُس خدایہ سٕندِس جنتس منز چُھ۔\n8. تہٕ سمیرنا کِس کلیساہٕکِس فرشتس لیکھِو؛ یم چیز چھہِ گۅڈنچہ تہ ٲخری کتھہِ ہند ونان، یُس مرُن اوس تہ زندہ۔\n9. بہٕ چُھس تُہند کامہِ تہٕ مصیبت تہٕ غربت، (مگر تہٕ چُھہ امیر آسان) تہٕ {بہٕ چُھس} تِمن ہُند کفر پتاہ یِم ونان چھِ زِ تِم چھِ یہودی تہٕ چِھنہٕ، مگر {چُھ} شیطان سٕنز عبادت خانہٕ۔\n10.\\tیِمن چیزن سٍتـ̡ گژھہِ نہٕ کانہہ تہِ خوفزدہ یُس تۅہہِ مُتٲثِر سپدِو، وُچھِو شیطان تہٕ یێلہِ تێلہِ ژٔٹِھتھ تہٕ یێلہِ تێلہِ ہُند مقدمہٕ ییہِ دِنہٕ۔ تہٕ ژے گژھہِ دہن دۅہن مصیبت: موتس تام وفادار روزُن، تہٕ بہٕ دِیہ ژے زندگی ہُند تاج۔\n11. یٔمِس کُن چُھ، سُہ بوزُن یُس روٝحہِ کلیساہن مَنٛز وَنُن چُھ۔ یُس غالب سپدِ، سہ گژھہِ نہ دۆیمہِ موتُک تکلیف دِنہٕ۔\n12. تہٕ پرگاموسس مَنٛز کلیساہٕ کِس فرشتس لیکھِو؛ یِم چیز چھِ ونان یٔمِس دۄن کنارن ہٕنز تیز تلوار آسہِ۔\n13. بہٕ چُھس چانہِ کامہِ پتاہ تہٕ یێتہِ تہٕ ژٕ روزان چھُ، {حتیٰ کہ} یێتہِ شیطان سٕنز نشست {چُھ} تہٕ ژے چُھکھ میٲنۍ ناو روزان تہٕ میانہِ ایمانس نکار کورمُت، تِمن دۅہن تہِ یێلہِ انٹیپاس میون وفادار شہید اوس، یُس ژے منزٕ مارنہٕ آو، یێتہِ شیطان روزان چُھ۔\n14.\\tمگر میہ چھیہ تۅہہِ خلاف کینہہ چیز، تکیازِ تۅہہ چھہ تِم یم بلعام سُند نظریہ تھاوان چھہِ، یمۍ بالکس ہیچھناوُن زِ بنی اسرائیل برونہہ کنہِ رُکاوٹ تراوُن، بتن ہندِ خٲطرٕ قربان کرنہٕ آمٕتۍ چیز کھٮ۪ن، تہٕ زنا کرُن۔\n15.\\tتہِ چھکھ تِم تہِ یِم نِکولایٹن ہُند نظریہٕ تھاوان چھِ، یُس میہ نفرت کران چھُ۔\n16. توبہ کرُن؛ نتہٕ بہٕ یِیہٕ جلدٕے ژےٚ نِش، تہٕ پننہِ تلوار سٍتۍ لڑہٕ تِمن خٕلاف لڑان۔\n17. یُس کُن چُھ، سُہ بوزُن یُس روٝحہِ کلیساہَن مَنٛز وَنُن چُھہ ۔ یُس غالب سپدِ، تس دِیہ میہ پوشیدٕ منا کھٮ۪نہٕ خٲطرٕ، تہٕ دِیہ تس اکھ سفید کن، تہٕ کٔنِس منز لیکھِتھ اکھ نۆو ناو، یُس نہ کانہہ تہِ انسان زانان چھُ، یُس رٔٹِتھ آسہِ۔\n18.\\tتہٕ تھیاتیراہس منز کلیساہٕکۍ فرشتس لیکھِو؛ یِم کتھٕ چھِ خدایہِ سُند فرزند ونان یٔمِس أچھ نارٕ کِس نارس ہِش چھِ، تہٕ تٔمۍ سٕندِ کھۅر چھِ نٔوۍ پیتل ہِش ۔\n19. بہٕ چُھس چانہِ کامہِ تہٕ خیرات، خدمت، تہٕ ایمان، تہٕ تُہند صبر تہٕ تُہند اعمال زانان۔ تہٕ ٲخری {to be} گوڑنکہٕ کھوتہٕ زیادٕ۔\n20. بہٕ چُھہ ژے سٍتـ̡ کینہہ کتھ کرنہٕ آمٕژ، تکیازِ ژے چھے تٔمِس زنانہٕ یِزبیلس سٍتـ̡ یۄسہٕ پانس پیغمبر ونان چِھ، میانین خادمن زناکاری کرنہٕ خٲطرٕ تہٕ بُتن ہٕندِ خٲطرٕ قربان کرنہٕ آمٕژ چیز کھٮ۪نہٕ خٲطرٕ ہیچھناونہٕ خٲطرٕ تہٕ ورغاونہٕ خٲطرٕ۔\n21. تہٕ مے دِژ أمِس پننہِ زناکٲری ہٕندِس توبہٕ خٲطرٕ جاے۔ تہٕ تٔمۍ کٔر نہٕ توبہٕ۔\n22.\\tوُچھ، بہٕ تراوٕ أمِس بسترس مَنٛز، تہٕ یِم أمِس سٍتـ̡ زنا کٔرِن تِمن سٍتـ̡ پى۪ٹھ۔\n23. تہٕ بہٕ مارٕ تٔمۍ سٕندِس شُرِ موتس سٍتـ̡ ۔ تہٕ سارنٕے کلیساہَن گژھہِ پتاہ زِ بہٕ چُھس سُہ یُس لگام تہٕ دِل ژھانڈان چُھس: تہٕ بہٕ دِیہ ژےٚ پرٮ۪تھ أکِس پننہِ کامہِ مُطٲبق۔\n24. مگر بہٕ چُھس تہٕ تھیتیراہس منز باقین لوکن تہٕ یِمن نہٕ یہ نظریہ چُھ، تہٕ یِمن نہٕ شیطان سٕنزِ گہرایی زانان چِھ، یِتھ کٔنۍ تِم کتھ کران چھِ۔ بہٕ تراوٕ نہٕ ژےٚ بیٚیہ کانٛہہ تہِ بوج۔\n25.\\tمگر یُس ژیہ {گوڈے} چھُ، توٚت تام تھپھ کٔرِتھ تھپھ کٔرِتھ۔\n26. یُس یُس فتح کرِ، تہٕ میانہِ کامہِ ہٕندِس ٲخرس تام برقرار تھاوِ، بہٕ دِیہٕ أمِس قومن پیٹھ طاقت:\n27.\\tتہٕ سُہ کرِ تِمن پیٹھ ششتٕرِ ہٕنزِ لورِ سٍتـ̡ حکوٗمت۔ یتھے پاٹھۍ چھہ کمہار سٕندِ بانہٕ یِن پھُٹراونہٕ یِن: یتھے پاٹھۍ میہ پننس مٲلس سٍتۍ میلہِ۔\n28. تہٕ بہٕ دِیہ تس صبحُک تارک۔\n29. یُس کُن چُھ، سُہ بوزُن یُس روٝحہِ کلیساہٕ سٍتـ̡ ونان چُھ۔","1. تہٕ ساردیس منز کلیساہٕکِس فرشتس لیکھِو؛ یِم چیز چھِ سُہ ونان یُس خدایہِ سٕندِ سَتھ روحہٕ تہٕ سَتھ ستارٕ چھِ۔ بہٕ چُھس چانہِ کامہِ پتاہ زِ ژے چُھس اکھ ناو یُس ژے زندٕ چُھ، تہٕ چُھس مٔرِتھ۔\n2. ہوشیار روزُن، تہٕ تِمن چیزن مضبوٗط روٗزِو یِم مرنہٕ خٲطرٕ تیار چھِ، کیازِ مے چُھنہٕ خدایہِ سٕندِ برونہہ کُن تُہند کٲم کامل لبنہٕ آمٕژ۔\n3. تێمہِ کِنۍ یاد تھاوُن تہٕ کِتھہ پٲٹھـ̡ چُھہ رٔٹِتھ تہٕ توبہ کٔرِو۔ تێلہِ اگر نہٕ ژے وُچھِو، بہٕ یِیہٕ ژےٚ ژوٗر سٕندِ پٲٹھۍ، تہٕ ژے گژھہِ نہٕ خبرے زِ بہٕ کمہِ بجہِ واتہِ ژے نِش۔\n4.\\tساردیَن مَنٛز تہِ چھِ کینہہ ناو یِمو نہٕ تِہٕندِس پلوَس ناپاک کٔرِتھ چھِ۔ تہٕ تِم پَکن میہ سٍتۍ سفیدس منز، تکیازِ تِم چھِ لایق۔\n5. یُس غالب سپدِ، سُہ گژھہِ سفید پوشاک لاگُن۔ تہٕ بہٕ کَرٕ نہٕ تٔمۍ سُند ناو زندگی ہٕنزِ کتابہِ منزٕ مِٹاونہٕ، مگر بہٕ کَرٕ تٔمۍ سُند ناو پننِس مٲلس برونہہ کُن، تہٕ تٔمۍ سٕندِس فرشتن برونہہ کُن۔\n6. یُس کَن چُھ، سُہ بوزُن یُس روح کلیسا سٍتـ̡ ونان چُھ۔\n7. تہٕ فلاڈیلفیاہس مَنٛز کلیساہٕ کِس فرشتس لیکھِو؛ یِم چیز چھِ ونان یُس پاک چُھ، یُس پٔز چُھ، یُس داؤد سٕنز کُنز آسہِ، یُس کھولان چُھ، تہٕ کانہہ تہِ انسان چُھہ بند کٔرِتھ۔ تہٕ چُھ بند کران، تہٕ کانہہ تہِ انسان چُھ نہٕ کھولان؛\n8. بہٕ چُھس چانہِ کامہِ پتہٕ: وُچھ، مے چُھس ژے برونہہ کُن اکھ یلہٕ دروازٕ تھوومُت، تہٕ کانہہ تہِ ہیکہِ نہٕ یہِ بند کٔرِتھ، تکیازِ ژے چُھس رژھ طاقت، تہٕ کورُن میون کلام پورٕ، تہٕ چُھکھ نہٕ میانہِ ناوُک انکار کٔرِتھ۔\n9.\\tوچھ، بہٕ بناو تِم شیطان سٕندِس عبادت خانہٕ، یُس ونان چھِ زِ تِم چھِ یہودی تہٕ چھِنہٕ مگر چھِ اپُز کران۔ وچھ، بہٕ بناوٕ تِم یِن تہٕ چُھس تہندٮ۪ن قدمن برونہہ کُن عبادت کرنہٕ خٲطرٕ، تہٕ یہ زاننہٕ خٲطرٕ زِ بہٕ چُھس ژے محبت کٔرمٕژ۔\n10.\\tکیازِ ژے چُھہ میانہِ صبرُک کلام برقرار تھوومُت، بہٕ تہِ بچاوٕ ژے آزمائش کِس وقتس نِش، یُس سارِنٕے دُنیاہس پیٹھ یِنہٕ یِنہٕ وٲلِس زمینس پیٹھ روزن والٮ۪ن ہٕندِس آزمٲیشہِ مۅکھہٕ۔\n11.\\tوُچھ، بہٕ چُھس جلدی آمُت: سُہ تھپھ تھپھ یُس ژے تھپھ کٔرِتھ، یُس نہ کانہہ تہِ انسان تُہند تاج رٔٹِتھ۔\n12. یُس فتح کرِ، سُہ کرِ بہٕ پننِس خدایہ سٕندِس مندرس مَنٛز اکھ تھم، تہٕ سُہ گژھِ نہٕ نیبر، تہٕ بہٕ لیکھہٕ تس پیٹھ پنُن خدایہ سُند ناو، تہٕ پننہِ خدایہ سٕندِ شہرُک ناو، یُس میانہِ خدایہ سٕندِ طرفہٕ اسمانہٕ منزٕ وسان چُھ، تہٕ بہٕ لیکھہٕ تس پیٹھ پنُن نوو ناو۔\n13. یُس کُن چُھ، سُہ بوزُن زِ روح چُھ کلیساہن مَنٛز کیا وَنان۔\n14. تہٕ لاودِکِس کلیساہٕکِس فرشتس لیکھِو؛ یِم کتھٕ چھِ آمین، وفادار تہٕ پٔزۍ گواہ، خدایہِ سٕنزِ تخلیقہٕ ہُند آغاز۔ {لاوڈیسین منز: یا، لاوڈیسیاہس منز}\n15. بہٕ چُھس چانہِ کامہِ پتاہ زِ ژٕ چُھہ نہٕ سردی تہٕ نہ گرم، بہٕ چُھس ژٕ سردی تہٕ گرم آسُن۔\n16. تیلہِ کیازِ ژے چُھکھ ہلکہٕ تہٕ نہ سردی تہٕ نہ گرم، بہٕ کٔرٕ ژے پننہ ٲسس منز۔\n17.\\tکیازِ ژے چُھس ونان زِ بہٕ چُھس امیر تہٕ مالہٕ سٍتـ̡ ہُریومُت، تہٕ چُھس نہٕ کُنہِ چیزٕچ ضرورت۔ تہٕ یہ چھُنہٕ خبر زِ تۅہہ چھِو بدبخت، بدبخت، غریب، تہٕ انہِ تہٕ ننگہٕ:\n18.\\tبہٕ چُھس ژے مشورٕ دِوان زِ نارس مَنٛز آزماونہٕ آمُت سۄنہٕ ہیٚیُن، یُتھ ژٕ امیر بٔنِتھ۔ تہٕ سفید پوشاک، تاکہ تۅہہ گژھ پلو لاگنہٕ، تہٕ {یُتھ} چانہِ ننگہٕ آسنٕچ شرمندگی گژھہِ نہٕ ظٲہر کرنہٕ۔ تہٕ پَنٕنۍ أچھ أچھن سٍتۍ مسح کٔرِتھ، یُتھ ژے وُچھِو۔\n19. یوتاہ بہٕ محبت کران چُھس، بہٕ چُھس ملامت تہٕ سزا دِوان: تَمہِ مۄکھٕ گژھہِ جوش، تہٕ توبہ کرُن۔\n20. وچھ بہٕ دروازس پیٹھ کھڑا تہٕ دستک دِوان: اگر کانہہ نفر میون آواز بوزان تہٕ دروازٕ کھولہٕ، بہٕ گژھہٕ أمس نِش، تہٕ تس سٍتـ̡ کھٮ۪وان تہٕ سُہ چُھس پانس سٍتـ̡ کھیوان۔\n21. یُس فتح حٲصل کرِ، بہٕ دِیہٕ بہٕ پننِس تختس پیٹھ پانس سٍتـ̡ بِہنہٕ خٲطرٕ، یێتھے پٲٹھـ̡ بہٕ تہِ فتح کٔرِمُت، تہٕ بہٕ بِہنہٕ پننِس مٲلس سٍتـ̡ تٔمۍ سٕندِس تختس پیٹھ۔\n22. یُس کُن چُھ، سُہ بوزُن یُس روح کلیساہَن مَنٛز وَنُن چُھ۔","1.\\tامہ پتہ وچھ میہ آسمانس منز اکھ دروازہ کھُلتھ تہ گۅڈنچہ آواز یۅسہ میہ بوز ٲس سۅ ٲس میہ سیتۍ کتھ کران زِ یہ ٲس میہ سیتۍ کتھ کران۔ یُس ووٚنمُت چھُ، یور یور تہٕ بہٕ ہاوٕ ژے تِم چیز یِم پتہٕ گژھن آسن۔\n2. تہٕ یکدم ووت بہٕ روحس منز: تہٕ وُچھتھ آو اسمانس منز اکھ تخت بِٹھاونہٕ، تہٕ {اکھ} بِہتھ تختس پیٹھ۔\n3.\\tتہٕ یُس بِہتھ اوس یُس جیسپر تہٕ سارڈین کٔنہِ ہیو وُچھان اوس، تہٕ تختس اندۍ اوس اکھ قوس قزح یُس زمرد ہیو نظرِ گژھان اوس۔\n4. تہٕ تختس اندۍ اندۍ ژور تہٕ وُہ نشستہٕ: تہٕ نشستن پیٹھ وُچھ میہ ژور تہٕ وُہ بزرگ سفید پوشاک لٲگِتھ بِہتھ۔ تہٕ تِمن ہٕندِس کلس پیٹھ ٲسۍ سۄنہٕ سُند تاج۔\n5. تہٕ تخت پیٹھٕ دراو بجلی تہٕ گرٛاے تہٕ آوازٕ، تہٕ {اتہِ} ٲسٕکھ سَتھ شمعہٕ دزان، یِم خدایہِ سٕندِ سَتھ روحہٕ چھِ۔\n6.\\tتہٕ تختس برونہہ کُن اوس شیشہ ہُند اکھ سمندر، تہٕ تختس اندۍ ژور جانور ٲسۍ برونہہ تہٕ پتھ کُن أچھن سٍتۍ بٔرِتھ۔\n7.\\tتہٕ گۄڈنیُک جانور اوس شیر ہیوٗ تہٕ دوٚیِم درندٕ اوس بَچھرِ ہیوٗ تہٕ ترٛیٚیِمِس درندَس اوس انسانہٕ سُند بُتھ تہٕ ژوٗرِم درندٕ اوس وُڈان عقاب ہیوٗ۔\n8.\\tتہٕ ژۅشونی درندن ٲس پریتھ اکس اندۍ پکھۍ شیہ پکھ۔ تہٕ {تِم} ٲسۍ أنٛدرٕ أچھن سٍتـ̡ بٔرِتھ: تہٕ تِم ٲسۍ نہٕ دۅہ راتس آرام کٔرِتھ، وَنُن، پاک، خداوند قادر مطلق، یُس اوس، تہٕ چُھ، تہٕ یُس یُس اوس، تہٕ چُھہ تہٕ یِنہٕ وول چُھ۔ {باقی...: Gr. no rest}\n9. تہٕ یێلہِ یێلہِ تِم درندٕ تٔمِس عَملَس تہٕ عزت تہٕ شُکرٕ دِوان یُس تختس پیٹھ بِہِتھ چُھ، یُس ہمیشہٕ خٲطرٕ زندٕ روزِ،\n10.\\tژور تہٕ وُہ بزرگ چھِ تختس پیٹھ بِہتھ أمِس برونہہ کُن پیوٚان، تہٕ یُس ہمیشہ زندٕ روزان چھُ، تہٕ تختس برونہہ کُن پنُن تاج تراوان تہٕ ونان چھِ،\n11. اے خداوند، تُہۍ چُھہ جلال تہٕ عزت تہٕ طاقت حٲصل کرنس لایق، تکیازِ ژے چھے سارِنٕے چیزن تخلیق کٔرمٕژ، تہٕ پننہِ خوشی خٲطرٕ چھِ تِم تہٕ تخلیق کرنہٕ آمٕتۍ۔","1. تہٕ میہ وُچھ تٔمِس دچھنہِ اتھس منز یُس تختس پیٹھ بِہتھ اوس، اتھ اندر تہٕ پٔتمہِ طرفہٕ لیکھِتھ ٲس اکھ کتاب، یتھ پیٹھ ستھ مہرٕ لٲگِتھ ٲس۔\n2.\\tتہٕ میہ وُچھ اکھ مضبوط فرشتہ یُس بَڑِ آوازِ سٍتۍ اعلان کران اوس، کُس چھُ کتاب کھولنس لایق، تہٕ اَمہ ہٕنزِ مُہر تراونس لایق۔\n3.\\tتہٕ آسمانس منز، نہ زمینس منز، نہ زمینس تلہ کنہِ تہِ انسان ہیوٚک نہ کتاب کھولِتھ، نہ اتھ پیٹھ نظر۔\n4. تہٕ بہٕ روو واریاہ زیادٕ، تکیازِ کٲنسہ تہِ انسان اوس نہٕ کتاب کھولنس تہٕ پرنس لایق لبنہٕ آمُت، تہٕ نہ اوس اتھ پیٹھ نظر تراونس لایق۔\n5. تہٕ اَکھ بزرگ چُھ مےٚ وَنُن، وَنُن نہٕ روُن: وُچھ، یہوداہٕ قبیلُک شیر، یُس داؤد سُند مول چُھ، چُھ کتاب کھولنہٕ خٲطرٕ تہٕ اَمہ ہٕنزِ سَتھ مہرٕ تراونہٕ خٲطرٕ غالب۔\n6. تہٕ وُچھ میہ تختس تہٕ ژۄن درندن منز، تہٕ بزرگن درمیان اوس اکھ کٹہٕ کۅکرٕ کھڑا یُس مارنہٕ آمُت اوس، یتھ ستھ سینگ تہٕ ستھ أچھ ٲس، یِم خدا سٕندِ ستھ روحہٕ چھِ سارِنٕے زمینس مَنٛز سوزنہٕ آمٕتۍ۔\n7.\\tتہٕ سُہ آو تہٕ تٔمِس دچھنہِ اتھہٕ سٍتـ̡ کتاب کٔڈِتھ یُس تختس پیٹھ بِہتھ اوس۔\n8.\\tتہٕ ییلہ تٔمۍ کتاب رٔٹِتھ، ژور جانور تہٕ ژور وُہ بٔڈۍ گٔیہِ کۅکرِ برونہہ کُن، یِمو منزٕ پرٮ۪تھ أکِس ہارپ، تہٕ سۅنہٕ شیشہٕ بٔرِتھ، یِم مُقدسن ہٕنز دُعا چھِ۔ {خوشبو: یا، بگرب}\n9.\\tتہٕ تِمو گۆو اکھ نۆو بٲتھ یتھ منز ونُن زِ تہٕ تۅہہ چھُکھ کتاب نِنس لایق، تہٕ اَمہ ہٕنزِ مہرٕ کھولنس لایق، کیازِ ژے آو مارنہٕ، تہٕ کورُکھ اسہِ پننہِ خونہٕ سٍتـ̡ پرٮ۪تھ رشتہٕ دارس سٍتـ̡ تہٕ لُکہٕ تہٕ قومہٕ سٍتـ̡ خدایہِ سٕندِس سٍتـ̡ نجات دِنہٕ۔\n10. تہٕ بنوو اسہِ پننِس خدایس بادشاہ تہٕ پادٕرۍ، تہٕ أسۍ کرو زمینس پیٹھ بادشاہ۔\n11. تہٕ مے وُچھ تہٕ بوز واریہن فرشتن ہٕنز آواز، تہٕ درندن تہٕ بزرگن ہٕنز آواز، تہٕ یمن ہُند تعداد اوس دَہ ساس تہٕ ساسہٕ ساس۔\n12.\\tبَڑِ آوازِ سٍتـ̡ وَنُن چُھہ سُہ کۅکرٕ یُس طاقت، دولت، تہٕ حکمت، تہٕ طاقت، تہٕ عزت، تہٕ جلال تہٕ برکت حٲصل کرنہٕ خٲطرٕ مارنہٕ آمُت اوس۔\n13. تہٕ پریتھ کانہہ مخلوق یُس آسمانس منز، زمینس منز، زمینس تل چُھ، تہٕ یُس سمندرس مَنٛز چُھ، تہٕ یُس تِمن مَنٛز چُھ، یُس سمندرس مَنٛز چُھ، تہٕ یُس تِمن مَنٛز چُھ، سُہ چُھ یہِ ونان زِ برکت، عزت، تہٕ جلال تہٕ طاقت، یُس تختس پیٹھ بِہِتھ چُھ، تہٕ کۅکرِ ہٕندِس خٲطرٕ ہمیشہٕ خٲطرٕ۔\n14.\\tژۅن درندن ووٚن آمین۔ تہٕ ژور تہٕ وُہ بزرگ پیوٚو تہٕ کٔرٕکھ أمِس سٕنز عبادت یُس ہمیشہ زندٕ روزان چُھ۔","1.\\tتہٕ میہ وُچھ ییلہ کۅکرِ مُہر کھولِتھ تہٕ بوز ژۅن درندن منز اکھ وونُن، یُس ژۅن درندن منز وُچھ۔\n2. تہٕ مے وُچھ تہٕ وُچھ اکھ سفید گُر: تہٕ یُس أمِس پیٹھ بِہتھ اوس، تس ٲس کمان۔ تہٕ أمِس آو اکھ تاج دِنہٕ: تہٕ سُہ درٛاو فتح کرنہٕ خٲطرٕ، تہٕ فتح کرنہٕ خٲطرٕ۔\n3.\\tتہٕ ییلہ تٔمۍ دۆیم مُہر کھول، میہ بوز دوٚیم درندہ ونان، آو وُچھ۔\n4.\\tتہٕ درٛاو بیاکھ گُر یُس وۄزُل اوس، تہٕ یُس اتھ پیٹھ بِہتھ زمینہِ نِش امن حٲصل کرنہٕ خٲطرٕ تہٕ تِم گژھن اکھ أکِس مارنہٕ خٲطرٕ دِنہٕ، تہٕ أمِس دِژ اکھ بٔڈ تلوار۔\n5. تہٕ ییلہ تٔمۍ تریم مُہر کھول، میہ بوز تریم درندہ ونان، آو وُچھ۔ تہٕ میہ وُچھ اکھ کرٛیٚہنہِ گُرۍ۔ تہٕ یُس أمس پیٹھ بِہتھ اوس، تس اوس اتھس منز اکھ جورٕ بیلنس۔\n6.\\tتہٕ بوز میہ ژۅن درندن منز اکھ آواز یُس اکھ پونسہ کٕنُک اکھ پیمائش، تہٕ أکِس پونسہٕ بدلہٕ تریہ پیمانہٕ جو۔ تہٕ {وُچھ} ژے کٔر نہٕ تیٖل تہٕ شرابس مجروح کرنہٕ۔ {اکھ پیمائش: لفظ choenix چُھ اکھ پیمائش یتھ منز اکھ شرابُک کوارٹ چُھ، تہٕ کوارٹُک بٔہِم حصہٕ چُھ}\n7. تہٕ ییلہ تٔمۍ ژوٗرِم مُہر کھول، میہ بوز ژوٗرِمِس درندٕ سٕنز آواز وَنُن، آو وُچھ۔\n8.\\tتہٕ میہ وُچھ اکھ زرد گُر: تہٕ تٔمۍ سُند ناو یُس أمس پیٹھ بِہتھ اوس موت، تہٕ جہنم آو تس سٍتـ̡ پتہٕ۔ تہٕ تِمن دِژ زمین کِس ژوٗرمِس حصس پیٹھ، تلوار سٍتۍ، فاقہٕ سٍتۍ، تہٕ موتہٕ سٍتۍ، تہٕ زمینہٕ کین درندن سٍتۍ مارنہٕ خٲطرٕ۔ {تِمن خٲطرٕ: یا أمِس خٲطرٕ}\n9. تہٕ ییلہ تٔمۍ پوٗنٛژِم مُہر کھول، میہ وُچھ قربان گاہس تَل تِمن ہٕندِ روحہٕ یِم خدایہ سٕندِ کلامہٕ خٲطرٕ مارنہٕ آمٕتۍ ٲسۍ، تہٕ تِمن ہٕنزِ گوٲہی خٲطرٕ:\n10.\\tتہٕ تِمو دِژ بَڑِ آوازِ سٍتـ̡ وۆن، اے خداوند، پاک تہٕ پٔزۍ، ژے کوتاہ تام چُھکھ نہٕ زمینس پیٹھ روزن والٮ۪ن سٍتـ̡ سانہِ خونُک فیصلہ تہٕ انتقام۔\n11.\\tتہٕ یِمو منزٕ آیہ پرٮ۪تھ أکِس سفید پوشاک دِنہٕ۔ تہٕ تِمن آو وننہٕ زِ تِم گژھن کینژَس کالس آرام کرُن، یوٚت تام تِہٕندِ سٲتھی خادم تہٕ تِہندۍ بٲے تہِ، یِم یِمن ہٕندۍ پٲٹھۍ مارنہٕ یِن۔\n12.\\tتہٕ میہ وُچھ ییلہ تٔمۍ شیٚیِم مُہر کھولمٕژ، تہٕ وُچھ اکھ زبردست زلزلہٕ۔ تہٕ آفتاب گوٚو مس کِس کُلِس ہیوٗ کرٛیٚہُن، تہٕ زون بنیوو خون۔\n13. تہٕ آسمانٕکۍ تارکھ پیوٚو زمینس پیٹھ، یِتھے پٲٹھۍ اکھ انجیر کُل پنن بے وقعت انجیر تراوان چُھ، ییلہ سُہ زوردار واو سٍتـ̡ ہلاونہٕ یوان چُھ۔ {بے وقعت انجیر: یا، سبز انجیر}\n14.\\tتہٕ ییلہ یہ یکوٹہ رٔلِتھ چُھہ آسمانس سٍتـ̡ دِنہٕ آمُت۔ تہٕ پرٮ۪تھ پہاڑ تہٕ جزیرٕ آیہ پننہِ جایہِ نِش نٮ۪بر کڈنہٕ۔\n15.\\tتہٕ زمینہِ ہٕندِس بادشاہ، بٔڈۍ مرد، تہٕ امیر تہٕ سردار کپتان، تہٕ طاقتور نفر، تہٕ پرٮ۪تھ کانہہ غلام تہٕ پرٮ۪تھ کانہہ آزاد انسان، ژوٗرِ پنُن پان پہاڑن ہٕندِس گۅپھن تہٕ پتھرن مَنٛز۔\n16.\\tتہٕ وونُن پہاڑن تہٕ پتھرن پیٹھ، یُس تختس پیٹھ بِہتھ چھُ، تہٕ کۅکرِ ہٕندِس قہر نِش ژوٗر تھاوُن:\n17. تٔمۍ سٕندِ قہر ہُند عظیم دۅہ آو آمُت۔ تہٕ کُس ہیکہِ کھڑا گژھِتھ؟","1. تہٕ یِمو چیزو پَتہٕ وُچھ میہ ژور فرشتہ زمینہٕ کِس ژۅشونی کونس پیٹھ کھڑا تہٕ زمینہِ ہٕندِس ژۅن واو رٔٹِتھ زِ واو گژھہِ نہٕ زمینس پیٹھ، نہ سمندرس پیٹھ، تہٕ کُنہِ کُلِس پیٹھ۔\n2. تہٕ میہ وُچھ بیاکھ فرشتہ مشرقہٕ کِنۍ کھسان، یتھ منز زندٕ خدایہ سٕنز مہر ٲس، تہٕ تٔمۍ کٔر ژۅن فرشتن بَڑِ آوازٕ سٍتۍ، یِمن زمینس تہٕ سمندرس دِنہٕ خٲطرٕ دِنہٕ آمُت اوس،\n3. یہ ونُن زِ زمینس تہٕ سمندرس تہٕ کُلِس کُلِس کٔرِو نہٕ تکلیف یوتام نہٕ أسۍ پننِس خدایہ سٕندِس بندس تِہندِس ڈٮ۪کہٕ پٲٹھـ̡ مُہر کٔرِو۔\n4.\\tتہٕ مے بوز تِمن ہُند تعداد یِم مُہر کٔرِتھ ٲسِتھ: {تہٕ تتہِ} آیہ بنی اسرائیل کین سارنٕے قبیلن منز اکھ ہتھ تہٕ ژتٲجی تہٕ ژور ساس مہرٕ کرنہٕ۔\n5. یہوداہٕ قبیلس مَنٛز آیہ باہ ساس مہر کرنہٕ۔ روبن سٕندِس قبیلس منز {ٲس} کٔر باہ ساس۔ گاد قبیلس مَنٛز کٔر باہ ساس۔\n6.\\tعسیر سٕندِس قبیلس مَنٛز کٔرِکھ باہ ساس۔ نیپتھالیم قبیلس منز کٔر باہ ساس۔ ماناسس قبیلس منز آیہ باہ ساس مہرٕ کرنہٕ۔\n7. شمعون سٕندِس قبیلس مَنٛز کٔرِکھ باہ ساس۔ لیوی سٕندِس قبیلس مَنٛز کٔر باہ ساس۔ اِساکر قبیلس مَنٛز کٔرِکھ باہ ساس۔\n8.\\tزابولون قبیلس مَنٛز آیہ باہ ساس مہرٕ کرنہٕ۔ یوسف سٕندِس قبیلس مَنٛز آیہ باہ ساس مہرٕ کرنہٕ۔ بنیامین سٕندِس قبیلس مَنٛز کٔرِکھ باہ ساس۔\n9.\\tاَمہِ پَتہٕ وُچھ میہ اَکھ بٔڈ لُکھ یُس نہٕ سارِنٕے قومن تہٕ رِشتہٕ دارَن تہٕ لُکن تہٕ زبانن ہٕندِس سٍتـ̡ گٔنزراوِتھ ہیوٚک نہٕ کانہہ تہِ بٔڈ لُکھ ہیوٚک کٔرِتھ، تختس برونہہ کُن تہٕ کۅکرِ ہٕندِس برونہہ کُن، یُس سفید پوشہٕ لٲگِتھ تہٕ اتھس منز اتھہٕ لٲگِتھ ٲس۔\n10. تہٕ وۆن بَڑِ آوازِ سٍتـ̡ وۆنُن، سٲنِس خدایہ سٕنز نجات یُس تختس پیٹھ بِہتھ چُھ، تہٕ کۅکرِ سٕندِس خداہس نجات دِنہٕ۔\n11.\\tتہٕ سٲری فرشتہ گٔیہِ تختس اندۍ کھڑا، تہٕ بٔڈۍ تہٕ ژۅن درندَن ہٕندِس اندۍ پکھۍ، تہٕ گٔیہِ تختس برونہہ کُن بُتھِس پیٹھ تہٕ خدایہ سٕنز پوٗزا کٔرٕن،\n12. آمین: برکت، تہٕ عظمت، تہٕ حکمت، تہٕ شکرگزاری، تہٕ عزت، تہٕ طاقت، تہٕ طاقت، سٲنِس خدایہ سٕندِ خٲطرٕ ہمیشہ ہمیشہ خٲطرٕ۔ آمین۔\n13.\\tتہٕ أکۍ بزرگن دیُت جواب دِتھ وونُن، یِم کیا چھِ یِم سفیدٕ پوشہٕ لٲگِتھ چھِ۔ تہٕ تم کتہِ آیہ؟\n14.\\tتہٕ میہ ووٚن أمِس جناب، ژیہ چھے پتاہ۔ تہٕ تٔمۍ ووٚن میہ زِ یِم چھِ تِم یِم بٔڈۍ مُصیبت منزٕ درٛامٕتۍ، تہٕ یِمو کٔرِکھ پَنٕنۍ پوشہٕ چھلنہٕ، تہٕ یِم کۅکرِ ہٕندِس خونس سٍتـ̡ سفید۔\n15. تێمہِ کِنۍ چھِ تِم خدایہ سٕندِس تختس برونہہ کُن، تہٕ تٔمۍ سٕندِس مندرس مَنٛز دۅہ راتس عبادت کران، تہٕ یُس تختس پیٹھ بِہتھ آسہِ سُہ یِمن مَنٛز روزُن۔\n16. تِمن گژھِ نہٕ مزید فاقہٕ تہٕ نہ پیاس ۔ نہ چھہ تمن پیٹھ آفتاب گاش تہ نہ کانہہ گرمی۔\n17.\\tیُس کۅکرِ تخت کِس درمِیان چُھ، سُہ کرِ تِمن کھٮ۪وان تہٕ تِمن آبہٕ کِس زندٕ چشمس کُن نِنہٕ، تہٕ خدایہ کرِ تِمن ہٕنزِ أچھن منزٕ سارِنٕے اشہ صاف کرنہٕ۔","1. تہٕ ییلہ تٔمۍ سٔتِم مُہر کھولِ، اسمانس منز ٲس نصف گھنٹس تام خاموشی۔\n2. تہٕ مے وُچھ سَتھ فرشتہٕ یِم خدایہِ برونہہ کُن کھڑا ٲسۍ۔ تہٕ تمن آیہ ستھ ٹرمپیٹ دِنہٕ۔\n3. تہٕ بیاکھ فرشتہ آو تہٕ کھڑا قربان گاہس پیٹھ، یتھ سنہٕ سُند سنسر اوس۔ تہٕ أمِس آو واریاہ بخور دِنہٕ، زِ سُہ کرِ تختس برونہہ کنہِ سنہٕ قربان گاہس پیٹھ سارنٕے سنتن ہٕنزِ دعاہٕ سٍتۍ پیش کرنہٕ۔ {پیشکش...: یا، یہ کٔرِو دعاہن منز شٲمل}\n4. تہٕ بخور ہُند دھوُن، {یُس مقدسن ہٕنزِ دعاہٕ سٍتـ̡ آو، ووت فرشتہٕ سٕندِ اتھہٕ سٍتـ̡ خدایہ سٕندِ برونہہ کُن۔\n5.\\tتہٕ فرشتہٕ رٔٹ سنسر تہٕ بٔرِتھ دِژُن قربان گاہُک نار، تہٕ ترٛٲوُن زمینس مَنٛز۔ تہٕ اَتہِ گٔیہٕ آوازٕ، گجگر، بجلی تہٕ زلزلہٕ۔ {into: or, upon}\n6.\\tتہٕ سَتھ فرشتہٕ یِمو سَتھ بُرق ٲسِو تِمو گٔیہِ پَنُن پان وَننہٕ خٲطرٕ تیار۔\n7.\\tگۅڈنِچ فرشتہٕ وُپھ تہٕ اَمہِ پَتہٕ ووت ژۅکہٕ تہٕ نار رٔلِتھ رٔلِتھ تہٕ تِم آیہ زمینس پیٹھ تراونہٕ۔ تہٕ کُلٮ۪ن ہُند تریم حصہ آو زٲلِتھ تہٕ سارِوٕے سبز گاسہٕ زالنہٕ۔\n8.\\tتہٕ دوٚیِم فرشتہٕ دِژ آواز، تہٕ یِتھٕ پٲٹھۍ اکھ بوٚڈ پہاڑ یُس نارٕ سٍتـ̡ دزان اوس، سمندرس مَنٛز تراونہٕ آمُت، تہٕ سمندرُک تریم حصہٕ گۆو خون۔\n9.\\tتہٕ سمندرس منز موجود مخلوقن ہُند تریم حصہ یُس سمندرس منز اوس، تہٕ زندگی ٲس، موٗد۔ تہٕ جہازُک تریم حصہٕ آو تباہ کرنہٕ۔\n10.\\tتہٕ تریم فرشتہ ووت تہٕ آسمانہٕ پیٹھٕ پیوٚو اکھ بۆڈ تارک، یُس چراغہ ہیو دزان، تہٕ سُہ پیوٚو دریاو کِس تریمس حصس پیٹھ، تہٕ آبہٕ کین چشمن پیٹھ۔\n11.\\tتہ ستارہ کس ناوس چھہ ورم ووڈ وننہ یوان: تہ آبک تریم حصہ بنیوو ورم ووڈ۔ تہٕ واریاہ نفر موٗدۍ آبہٕ سٍتۍ، تکیازِ تِم ٲسۍ تلخ بناونہٕ آمٕتۍ۔\n12. تہٕ ژوٗرِم فرشتہٕ دِژ تہٕ آفتابُک تریم حصہٕ آو مارنہٕ، تہٕ زونہِ ہُند تریم حصہٕ تہٕ تارن ہُند تریم حصہٕ۔ تہ یتھے پاٹھۍ اوس یمن ہند تریم حصہ انہِ گوٚٹ گومت، تہ دۅہ اوس نہ امہ کس تریمس حصس منز گاش تہ رٲژ تہِ۔\n13. تہٕ مے وُچھ تہٕ بوز اکھ فرشتہ یُس آسمانس منز وُڈان اوس، یُس بَڑِ آوازٕ سٍتـ̡ وَنُن چُھ، افسوس، افسوس، زمین کین بسکینن ہٕندِ خٲطرٕ، یِم وُنیُک تام وُنہِ وُنہِ وٕنـ̡ چِھہ!","1. تہٕ پوٗنٛژمہِ فرشتہٕ وُچھ آسمانہٕ پٮ۪ٹھٕ زمینس پیٹھ اکھ تارٕ پیوٚو، تہٕ أمِس دِژ بٔنِس کھۅڈٕچ کُنز۔\n2. تہٕ تٔمۍ کھول بونہٕ روٚس گڑھ۔ تہٕ تتہِ دراو کھۅنہِ منزہ اکھ دھواں، یُس أکِس بٔڈِ بھٹہِ ہُند دھوہٕ اوس۔ تہٕ آفتاب تہٕ ہوا گٔیہٕ گڑھہٕ کہ دھونہٕ کہ وجہ سٔتۍ تاریک گومُت۔\n3. تہٕ دوٚمہِ منزٕ دراو زمینہِ پیٹھ، تہٕ تِمن دِژ طاقت، یِتھ کٔنۍ زٔمیٖنہِ ہٕندِس بِچھوَس طاقت چھِ۔\n4. تہٕ تِمن آو حکم دِنہٕ زِ تِم گژھن نہٕ زمینہِ ہٕندِس گاسَس نقصان دِنہٕ، نہ کُنہِ سبز چیز، نہ کُلِس تہِ۔ مگر صرف تِم انسان یمن ہٕندِس ڈیکس پیٹھ خدایہِ سٕنز مُہر آسہِ۔\n5.\\tتہٕ تِمن اوس یہ دِنہٕ آمُت زِ تِم گژھن نہٕ تِمن مارنہٕ بلکہ یِمن پانژن ریتن عذاب دِنہٕ یُن: تہٕ تِمن ہُند عذاب اوس بِچھو سُند عذاب، یُس أکِس انسانس ٹاس دِوان چھُ۔\n6. تہٕ تِمن دۅہن منز گژھن انسان موتُک ژھانڈان، تہٕ سُہ میلہِ نہٕ۔ تہٕ مرنُک خواہش، تہٕ موت ژلہِ تِمن نِش۔\n7. تہٕ ٹِڈین ہٕنز شکلہٕ آسہٕ جنگہٕ خٲطرٕ تیار گُرٮ۪ن ہٕندۍ پٲٹھۍ۔ تہٕ تِہندِس کلس پیٹھ ٲسۍ سۅنہٕ ہیوٗ تاج، تہٕ تِہندِ بُتھ ٲسۍ انسانن ہٕندِس بُتھِس پٲٹھۍ۔\n8. تہٕ تِمن ٲسۍ زنانن ہٕندِس مَس ہٕندۍ پٲٹھۍ، تہٕ تِہٕندِ دند ٲسۍ شیرن ہٕندِس دندٕکۍ پٲٹھۍ۔\n9.\\tتہٕ تِمن آسہٕ سینہٕ پٲٹھۍ، یِتھ کٔنۍ زِ یہِ ٲس ششتٕرٕچ سینہٕ پٲٹھۍ۔ تہٕ تہندٮ۪ن پکھن ہٕنز آواز ٲس جنگس منز ژلنہٕ والٮ۪ن گُرٮ۪ن ہٕندِس رتھن ہٕنز آواز۔\n10.\\tتہٕ تِمن ٲس لٔٹ بچھو ہٕندۍ پٲٹھۍ، تہٕ تِمن ہٕندِس لٔٹِس منز ٲس ڈنگہٕ: تہٕ تِہُند طاقت اوس پانژن ریتن انسانس تکلیف دِنُک طاقت۔\n11.\\tتہٕ تِمن پیٹھ اوس اکھ بادشاہ، {یُس} بونہٕ روٚس کھۅڈُک فرشتہٕ، یٔمۍ سُند ناو عبرانی زبانہِ مَنٛز {چُھ} آبادون، مگر یونانۍ زبانہِ مَنٛز چھُ {تٔمِس} ناو اپولین۔ {اپولین: یعنی اکھ تباہ کار}\n12.\\tاکھ مصیبت چھہ پتھ کال۔ {تہٕ}، وُچھ، پتہٕ تہٕ بییہٕ زٕ مصیبت۔\n13. تہٕ شییِم فرشتہٕ وُن تہٕ بوز سۅنہٕ قربان گاہ ہٕندِس ژۅن سینٛگن منزٕ اکھ آواز یُس خدایہ برونہہ کُن چھُ،\n14.\\tشیمہِ فرشتہ یس بُرپھ اوس، ژۅن فرشتہ یُس دریائے فرات کِس بٔڈِس مَنٛز بند چھِ۔\n15.\\tتہٕ ژۅن فرشتہ آیہ یلہٕ تراونہٕ، یِم أکِس گھنٹس تہٕ أکِس دۅہس تہٕ أکِس ریتس تہٕ أکِس ؤریس خٲطرٕ تیار کرنہٕ آمٕتۍ۔ {أکِس گھنٹس خٲطرٕ: یا، أکِس گھنٹس پیٹھ}\n16.\\tتہٕ گُرۍ سوارن ہٕندِ فوجُک تعداد اوس زٕ لچھ ساس: تہٕ مے بوز تِمن ہُند تعداد۔\n17.\\tتہٕ یِتھٕ پٲٹھۍ وُچھ میہ وژنس منز گُرۍ، تہٕ یِمن پیٹھ بِہتھ ٲسۍ، یِمن ہٕندِس سینہٕ سٍتـ̡ نارٕچ تہٕ یعقوبت تہٕ گندھٕچ ٲس، تہٕ گُرٮ۪ن ہٕندِ کلہٕ ٲسۍ شیرن ہٕندِس کلہٕ ہٕندۍ پٲٹھۍ۔ تہٕ یِہٕندِ ٲسو منزٕ نار تہٕ دوٚہہ تہٕ گندھ۔\n18.\\tیِمن ترٮن ہٕندِ دٔسۍ مارنہٕ آمُت نفرن ہُند تریم حصہ، نارٕ سٍتۍ، تہٕ دھونہٕ سٍتۍ، تہٕ گندٕمہٕ سٍتۍ، یُس تہندِ ٲسس منزٕ نیران اوس۔\n19.\\tتِہُند طاقت چُھ تِہٕندِس ٲسس مَنٛز، تہٕ تِمن ہٕندِس لٔٹِس مَنٛز، تِکیازِ تِہٕنزِ لٔٹ ٲس ناگن ہٕندۍ پٲٹھۍ، تہٕ ٲسٕس کلہٕ، تہٕ تِمن سٍتـ̡ چِھ تِمن دَگ دِوان۔\n20. تہٕ باقٕے لُکھ یِم نہٕ یِمو وُپھو سٍتـ̡ مارنہٕ آمٕتۍ، تِمو کٔر نہٕ پننین اتھن ہٕندِس کامہِ سٍتـ̡ توبہ زِ تِم گژھن نہٕ شیطانن ہٕنز، سۄنہٕ تہٕ رۄپھ، پیتل، تہٕ کنن تہٕ لٔکرِ ہٕندِس بُتن ہٕنز پوجا کٔرِتھ، یِم نہٕ وُچھِتھ تہٕ بوزِتھ تہٕ پکان چھِ۔\n21. نہ کٔر تِمو پننین قتلن سٍتۍ، نہ پننین جادوگرن سٍتۍ، نہ پننہِ زناکاری سٍتۍ، تہٕ ژوٗرِ ہٕندِس سٍتـ̡ توبہٕ۔","1.\\tتہٕ میہ وُچھ بیاکھ طاقتور فرشتہ آسمانہٕ پیٹھٕ ؤسِتھ، اوٚبرٕ لٲگِتھ اوسُس: تہٕ تٔمۍ سٕندِس کلس پیٹھ اوس اکھ قوس قزح تہٕ تٔمۍ سُند بُتھ اوس آفتاب، تہٕ تٔمۍ سٕندِس کھۅر نارٕکۍ تھمَن ہٕندۍ پٲٹھۍ۔\n2.\\tتہٕ أمِس اتھس منز ٲس اکھ لۄکٕٹ کتاب یلہٕ، تہٕ تٔمۍ تھووُن پنُن دٔچھُن کھوٚر سمندرس پیٹھ، تہٕ کھوورِ کھوٚر زمینس پیٹھ،\n3.\\tتہٕ وۆن بَڑِ آوازِ سٍتـ̡ یِتھٕ پٲٹھـ̡ سٕہہ ہٕندِس کُنہِ سٍتـ̡ گٔژِھتھ تہٕ ییلہ أمِس کٔرِتھ وۆن سَتھ گرٛیٚجہٕ ہٕنز آواز۔\n4.\\tتہٕ ییلہ سَتھ گجگرن پنٕنۍ آواز کٔر، بہٕ اوسُس لیکھُن: تہٕ بوز اسمانہٕ پیٹھٕ اکھ آواز یُس میہ ونان اوس، تِم کتھٕ بند کٔرِو یِم سَتھ گرٛیٚجہٕ کٔرۍ، تہٕ تِم لیکھِو نہٕ۔\n5. تہٕ یُس فرشتہٕ یُس میہ سمندرس تہٕ زمینس پیٹھ کھڑا وُچھمُت اوس، تُل اسمانس کُن اتھہٕ،\n6. تہٕ تٔمِس سٕندِس سٍتـ̡ یُس ہمیشہ زندٕ چُھ، یُس اسمانس تہٕ اَتھ مَنٛز موجود چیز، تہٕ اَتھ مَنٛز موجود چیز، تہٕ سمندر، تہٕ تِمن چیزن ہُند قَسم کٔرِو یُس نہٕ وُنیُک وق آسُن:\n7.\\tمگر سٔتِم فرشتہٕ سٕنزِ آوازِ ہٕندِس دۅہس منز، یێلہِ سُہ بوزُن شروع گژھہِ، خدایہِ سُند اسرار گژھہِ ختم سپدُن، یِتھ کٔنۍ تٔمۍ پننین بندن پیغمبرن ہُند اعلان کورمُت۔\n8. تہٕ یُس آواز میہ آسمانہٕ پیٹھہٕ بوزمُت اوس، سُہ کٔر میہ بییہِ کتھ تہٕ وونُن، گژھ {تہٕ} سُہ لۄکٕٹ کتاب یُس فرشتہٕ سٕندِس اتھس منز یلہٕ چُھ، یُس سمندرس تہٕ زمینس پیٹھ کھڑا چُھ۔\n9. تہٕ بہٕ ووت فرشتس نِش، تہٕ وونُس زِ مے دِژ لۄکٕٹ کتاب۔ تہٕ تٔمۍ ووٚن میہ نِن، نِش تہٕ کھیوٚن۔ تہٕ یہ گژھہِ تۅہہِ ہُند یٔڈ تلخ مگر یہ آسہِ چانہِ ٲسس منز ماچھ ہیوٗ موٚدُر۔\n10. تہٕ مے کٔر فرشتہٕ سٕندِ اتھہٕ منزٕ لۄکٕٹ کتاب تہٕ کھیوٚن سُہ ۔ تہٕ یہ اوس میٲنس ٲسس منز ماچھہِ ہیوٗ موٚدُر: تہٕ ییلہ میہ یہ کھیوٚو، میون اڈ اوس تلخ۔\n11.\\tتہٕ تٔمۍ ووٚن میہ زِ ژے پزِ واریاہن لوکن تہٕ قومن تہٕ زبانن تہٕ بادشاہن برونہہ کنہِ دُبارٕ پیشن گویی کرٕنۍ۔","1.\\tتہٕ دِژ میہ لٔرِس ہیوٗ اکھ لٔر دِنہٕ، تہٕ فرشتہ ووٚتھ ووٚتھ، تہٕ ووٚتھ خدایہ سُند مندر تہٕ قربان گاہ تہٕ یِم اتھ منز عبادت کران چھِ۔\n2.\\tمگر یُس دربار مندرس ورٲے آسہِ، سہ گژھہِ تراوُن، تہٕ پیمائش کرُن نہٕ۔ تکیازِ یہِ چُھ غیر قومن دِنہٕ آمُت: تہٕ مقدس شہرس منز گژھن تِم ژتٲجی تہٕ دۅن ریتن قدمن تل پکان ۔ {ترٲوِو: Gr. Cast Out}\n3. تہٕ بہٕ دِیہ پننین دون گوااہن {طاقت}، تہٕ تِم کرِ ساس زٕ ہتھ تہٕ تریہ ہتھ دۅہن پیشن گویی کرنہٕ۔ {بہٕ دِیہ...: یا، بہٕ دِیہ پننین دون گوااہن تاکہ تم کرن پیشن گوئی}\n4. یِم چھِ زٕ زیتون کُلۍ، تہٕ زٕ شمعدان یِم زمینہٕ کِس خداہس برونہہ کُن کھڑا چھِ۔\n5. تہٕ یێلہِ کانہہ نفر تِمن تکلیف دِیہِ، تہٕ یێلہِ کانہہ نفر تِمن دُشمن دِیہِ تہٕ یێلہِ کانہہ نفر تِمن تکلیف دِیہِ، سُہ گژھہِ یِتھٕ پٲٹھۍ مارنہٕ یُن۔\n6.\\tیِمن چُھ اسمانس بند کرنُک اختیار تھاوان، یُتھ نہٕ تِمن ہٕنزِ پیشن گویی ہٕندِس دۅہہَس مَنٛز روٗد پیٚیہِ، تہٕ یِمن آبس پیٹھ چُھ اِختِیار حٲصِل کٔرِتھ، تہٕ یِمن ہٕندِس سٍتـ̡ یێلہِ یێلہِ سٍتـ̡\n7. تہٕ ییلہ تِم پنٕنۍ گوٲہی مُکمل کرِ، سُہ درندہ یُس بٔنِس کھۅنہٕ منزٕ کھسان چُھ، سُہ کرِ تِمن خلاف جنگ، تہٕ کرِ تِمن پیٹھ قابو پاونہٕ تہٕ مارِ۔\n8. تہٕ تِہٕنزِ لاشہٕ گژھن عظیم شہرٕ کِس سڑکہِ مَنٛز، یَتھ روحٲنی طور سدوم تہٕ مصر ونان چھِ، یتہِ سٲنـ̡ رب تہِ اوس مصلوب کرنہٕ آمُت۔\n9.\\tتہٕ لوکن تہٕ رشتہ دارن تہٕ زبانن تہٕ قومن ہٕندِس لاشس ساڑن تریہ دۅہن وُچھن، تہٕ تِمن ہٕنزِ لاشہٕ قبرن مَنٛز تراوُن دِنہٕ یِن۔\n10. تہٕ یِم زمینہِ پیٹھ روزان چھِ تِمن پیٹھ شاد گژھن، تہٕ خۅش گژھن تہٕ سوزن اکھ أکِس تحفہٕ۔ تکیازِ یمو دۅشوے پیغمبرن کٔر تمن ستائے یم زمینس پیٹھ روزان ٲسۍ۔\n11.\\tتہٕ ساڑن تریہ دۅہہٕ پَتہٕ گۆو خدایہ سُند روح زندگی تِمن مَنٛز دٲخل، تہٕ تِم کھٔدۍ پننین قدمن پیٹھ۔ تہٕ یِمن وُچھن تِمن پیٹھ سٮ۪ٹھاہ خوف پییہِ۔\n12. تہٕ تِمو بوز آسمانہٕ پیٹھٕ اکھ بٔڈ آواز یُس تِمن ووٚنمُت چھُ، یُس یور وُچھِو۔ تہٕ تِم ووت أکِس اوٚبرس منز جنتس تام۔ تہٕ تہندیو دُشمن وچھ تِم۔\n13. تہٕ أتھۍ ساعتہ آو اکھ زبردست زلزلہ، تہٕ شہرُک دٔہِم حصہٕ پیوٚو تہٕ زلزلہٕ مَنٛز گٔیہٕ ستھ ساس انسان مارنہٕ۔ {of men: Gr. Names of Men}\n14.\\tدۆیم مصیبت چھہ پتھ کال۔ {تہٕ}، وچھ تریم مصیبت چھے جلدٕے یوان۔\n15.\\tتہٕ سٔتِم فرشتہٕ دِژ آواز۔ تہٕ آسمانس مَنٛز ٲس بٔڈ آوازٕ یِم ونان چھِ، یێمہِ دُنیاہٕچ بادشٲہی چھے سٲنِس آغہٕ سٕنزِ تہٕ تٔمۍ سٕندِس مسیح سٕنزِ بادشٲہی بنیمٕژ۔ تہٕ سُہ روزِ ہمیشہٕ خٲطرٕ بادشاہ۔\n16.\\tتہٕ ژور تہٕ وُہ بزرگ، یِم خدایہِ سٕندِس بُتھِس پیٹھ بِہِتھ، تہٕ کٔرٕکھ خدایہِ سٕنز پوٗزا\n17. یہ ونِتھ زِ أسۍ چُھہ تُہند شُکر ادا کران اے خداوند قادر مطلق، یُس چُھہ تہٕ یُس یُس چُھہ یُس تہٕ یِنہٕ وول چُھ۔ تکیازِ ژے چُھکھ پنُن عظیم طاقت پانس نِش نِمُت، تہٕ کٔرٕکھ حکوٗمت۔\n18.\\tتہٕ قومن ہٕندِ غصہٕ ووت تہٕ تُہند غضب آو تہٕ مُردن ہُند وق آو تِمن ہُند فیصلہ کرنہٕ، تہٕ تۅہہ گژھہِ پننین خادمَن، پیغمبرن تہٕ مقدسن تہٕ تُہندِ ناوٕ کھوژان یُس لۄکٹۍ تہٕ بٔڈۍ ناوُک خوف تھاوان چھُ۔ تہٕ پزِ تِم تباہ کرٕنۍ یِم زمینہِ تباہ کران چھِ۔ {زمینہِ تباہ کرُن: یا کرو زمینہِ خراب کرُن}\n19.\\tتہٕ خدایہ سُند مندر آو آسمانس مَنٛز کھولنہٕ، تہٕ تٔمۍ سٕندِس مندرس مَنٛز آو تٔمۍ سٕندِس وصیتُک صندوق وُچھنہٕ۔ تہٕ اَتہِ ٲس بجلی تہٕ آوازہٕ تہٕ گُرگٲر تہٕ زلزلہٕ تہٕ بٔڈ ڈولہٕ۔","1. تہٕ آسمانس مَنٛز گۆو اکھ بوٚڈ عجوب۔ اکھ زنانہِ آفتابس سٍتۍ پوش تہ زون تہ کلس پیٹھ باہ ستارن ہند تاج: {حیرت: یا، نشان}\n2.\\tتہٕ سۅ ٲس شُرِ سٍتـ̡ روُن، زینہٕ وِزِ مُشکِل تہٕ دَگ گٔیہِ۔\n3. تہٕ آسمانس منز آو بیاکھ اکھ عجوبہ ظٲہر۔ تہٕ وُچھِو اکھ بوٚڈ وۄزُل ڈریگن، یٔمِس سَتھ کلہٕ تہٕ داہ سینٛگ تہٕ ستھ تاج چھِ۔ {حیرت: یا، نشانہٕ}\n4.\\tتہٕ تٔمۍ سٕنزِ لٔٹ لٔج آسمانہٕ کِس ستارن ہُند تریم حصہٕ، تہٕ ترٛٲوِن زمینس پیٹھ، تہٕ ڈریگن کھڑا زنانہِ برونہہ کُن یُس زیٚنہٕ خٲطرٕ تیار اوس، یُس زیٚنہٕ وِزِ پنُن شُر کھٮ۪نہٕ خٲطرٕ۔\n5. تہٕ تٔمۍ زٲو اکھ مرد شُر، یُس سارنٕے قومن پیٹھ ششتٕرٕچ لٔر ہیتھ حکومت کرُن اوس، تہٕ تٔمۍ سُند شُر آو خدایس نِش رٔٹنہٕ، تہٕ تٔمۍ سٕندِس تختس پیٹھ۔\n6.\\tتہٕ زنانہٕ ژٔل بیابانس مَنٛز، یتہِ أمِس خدایہ سٕندِ طرفہٕ تیار کرنہٕ آمٕژ جاے چِھ، یُتھ تِم أمِس اتہِ ساس زٕ ہتھ تہٕ تریہ ہتھ دۅہن کھیٚوان دِنہٕ۔\n7. تہٕ جنتس منز اوس جنگ: میکائیل تہٕ تٔمۍ سٕندِس فرشتن لوٚڈ ڈریگنس خٕلاف۔ تہٕ ڈریگن لوٚڑ تہٕ تٔمۍ سٕندۍ فرشتہٕ،\n8.\\tتہٕ گٔیہ نہٕ غالب۔ نہ ٲس تہنز جاے جنتس منز میلان۔\n9. تہٕ بٔڈ ڈریگن آو کڈنہٕ، سُہ پرون ناگ، یُس شیطان تہٕ شیطان ونان چُھ، یُس سارِنٕے دنیاہس دھوکہٕ دِوان چُھ، سُہ آو زمینس مَنٛز کڈنہٕ، تہٕ تٔمۍ سٕندِ فرشتہٕ کٔرِکھ أمِس سٍتـ̡ کٔڈِتھ۔\n10. تہٕ بوز اسمانس مَنٛز اَکھ بَڑِ آواز یُس وَنُن چُھ، وُنہِ چُھ نجات تہٕ طاقت، تہٕ سانہِ خدایہِ سٕنز بادشاہی تہٕ تٔمۍ سٕندِس مسیح سٕنز طاقت، یێمہِ سٍتـ̡ سٲنـ̡ خدایہِ سٕندِس قٕسمس سٍتـ̡ دۅہہٕ تہٕ راتس سٍتـ̡ الزام دِنہٕ آمُت چُھ۔\n11. تہٕ تِمو کٔر أمِس کۅکرِ سٕندِ خونہٕ سٍتـ̡ تہٕ پنٛنہِ گوٲہی ہٕندِ کلامٕ سٍتـ̡ مغلوب کرنہٕ۔ تہٕ تِم ٲسۍ نہٕ مرنس تام پننہ زندگی محبت کران۔\n12. تَمہِ مۄکھٕ کٔرِو خۅش گٔژھِو، اسمانَن تہٕ یِمن مَنٛز روزَن وٲلۍ۔ زمینہِ تہٕ سمندرٕکۍ بسکینن ہُند افسوس! تکیازِ شیطان چُھ توے نِش سٮ۪ٹھاہ غصہٕ سٍتـ̡ آمُت، تکیازِ تس چُھ پتاہ زِ أمِس چُھ کم وقت۔\n13. تہٕ ییلہ ڈریگن وُچھ زِ سُہ آو زمینس پیٹھ تراونہٕ، تٔمۍ کٔر زنانہِ ستاونہٕ یٔمۍ مرد {شُر} پٲدٕ کٔر۔\n14.\\tتہٕ زنانہِ آیہ أکِس بٔڈِ عقاب سٕندِ زٕ پکھہٕ دِنہٕ، یُتھ سُہ بیابانس مَنٛز، پننہِ جایہِ منز، ییتہِ أمِس کینژَس کالس تہٕ نصف وقتس تام ناگ سٕندِ بُتھِ پیٹھٕ پرورش سپدان چھِ۔\n15.\\tتہٕ ناگن کٔر زنانہِ ہٕندِس آبس سٍتـ̡ سٔہلاب ہٕندِس آبس سٍتـ̡ دِنہٕ۔\n16. تہٕ زمینن کٔر زنانہِ مدد، تہٕ زمینن کھول پنن ٲس، تہٕ گِلہٕ سٔہلاب یُس ڈریگن پننہٕ ٲسٕ منٛزٕ تروو۔\n17.\\tتہٕ ڈریگن گوٚو زنانہِ سٍتـ̡ شرارت، تہٕ گۆو پننہِ اولادٕ سٍتـ̡ جنگ کرنہٕ خٲطرٕ، یُس خدایہ سٕندِس حکمس پیٹھ عمل کران چُھ، تہٕ عیسیٰ مسیح سٕنز گوٲہی دِنہٕ خٲطرٕ۔\n18. تہٕ بہٕ کھڑا سمندرٕ کِس سیکہِ پیٹھ۔","1.\\tتہٕ وُچھ سمندرٕ منزٕ اکھ درندٕ ووٚتھ، یٔمِس سَتھ کلہٕ تہٕ داہ سینگ ٲسۍ، تہٕ تٔمۍ سٕندِس سینگس پیٹھ ٲس داہ تاج، تہٕ تٔمۍ سٕندِس کلس پیٹھ اوس کفر ہُند ناو۔ {ناو: یا، ناو}\n2.\\tتہٕ سُہ جانور یُس میہ وُچھمُت اوس سُہ اوس سٕہہ سٕندِس پٲٹھۍ، تہٕ تٔمۍ سٕندِ کھۅر ٲسۍ شیر سٕندِس کھورِ ہیوٗ تہٕ تٔمۍ سٕندِ ٲسس شیر سٕندِس ٲسس ہیوٗ تہٕ ڈریگن دِژ أمِس پنُن طاقت، تہٕ پنٕنۍ نشست تہٕ بٔڈ اختیار۔\n3.\\tتہٕ میہ وُچھ تٔمۍ سُند اکھ کلہٕ یُس زخم کٔرِتھ مرُن۔ تہٕ تٔمۍ سُند مہلک زخم گوٚو ٹھیٖک: تہٕ سورُے دنیا اوس درندٕ پتہٕ حیران۔ {زخمی: Gr. Slain}\n4.\\tتہٕ تِمو کٔر تٔمِس ڈریگنس پوٗزا یُس درندَس طاقت دِیُت، تہٕ تِمو کٔر أمِس درندٕچ پوٗزا کٔرِتھ یہِ ونان زِ کُس چُھہ درندَس ہِش ہیوٗ چُھ؟ أمِس سۭتۍ کُس چھُ جنگ کرنس قٲبل؟\n5. تہٕ أمِس دِنہٕ آمُت اَکھ بٔڈ کتھ تہٕ کُفر کَرٕنـ̡ ۔ تہٕ أمِس آو ژتٲجی (تہٕ} دۄن رٮ۪تن جٲری تھاونُک اختیار دِنہٕ۔ {جٲری تھاوُن: یا، جنگ کرنہٕ خٲطرٕ}\n6. تہٕ تٔمۍ کھول خدایس خلاف کفر کٔرِتھ پننِس ناو، تہٕ تٔمۍ سٕندِس خیمہ خانس تہٕ جنتس مَنٛز روزن والٮ۪ن ہٕنز توہین کرنہٕ خٲطرٕ۔\n7. تہٕ أمِس دِنہٕ آمُت زِ سُہ کرِ مقدسن سٍتـ̡ جنگ کرنہٕ، تہٕ تِمن پیٹھ فتح حٲصل کرنہٕ خٲطرٕ، تہٕ أمِس دِیُت سارنٕے رشتن تہٕ زبانن تہٕ قومن پیٹھ طاقت۔\n8. تہٕ یُس سارِوٕے زمینہِ پیٹھ روزان چُھ، تٔمۍ سُند ناو چُھنہٕ دنیاہٕچ بُنیاد پٲٹھـ̡ مارنہٕ آمٕژ کامہِ زندگی ہٕندِس کتابہِ مَنٛز لیکھنہٕ آمُت۔\n9.\\tاگر کٲنسہِ انسانس کُن آسہِ، سُہ بوزُن۔\n10.\\tیُس قٲد سپدِ، سُہ گژھہِ قٲد کرنہٕ یُن: یُس تلوار سٍتـ̡ ماران چُھ، سُہ گژھہِ تلوار سٍتـ̡ مارنہٕ یُن۔ یتہِ چُھ مُقدسن ہُند صبر تہٕ اعتقاد۔\n11.\\tتہٕ وُچھ بیاکھ جانور یُس زمینہِ منزہ نیران اوس۔ تہٕ أمِس ٲسۍ کۅکرِ ہٕندۍ پٲٹھۍ زٕ سینٛگ، تہٕ سُہ اوس ڈریگن سٕندۍ پٲٹھۍ بولان۔\n12. تہٕ سُہ چُھ پانس برونہہ کُن گۅڈنِکِس درندٕ سُند سورُے طاقت استعمال کٔرِتھ، تہٕ دِوان زمینہٕ تہٕ یِم اتھ منز روزن وٲلِس گۄڈنِکِس درندٕ سٕنزِ پوجا کرنہٕ خٲطرٕ، یٔمۍ سُند مہلک زخم ٹھیک گومُت۔\n13. تہٕ سُہ چُھ بٔڈۍ عجائب کٔرِتھ، یێلہِ سُہ چُھ انسانس ہٕندِس نظرس منز آسمانہٕ سٍتـ̡ زمینہِ پى۪ٹھـ̡ نار وسناوُن،\n14.\\tتہٕ یِم زمینس پیٹھ روزن وٲلِس معجزو سٍتـ̡ دھوکہٕ دِوان یِم أمِس درندٕ سٕندِس نظرس منز کرنٕچ طاقت ٲس۔ تِمن وَنُن یِم زمینس پیٹھ روزان چھِ، زِ تِم بناوٕن أمِس درندٕ سٕنز شکلہٕ، یٔمِس تلوار سٍتۍ زخم اوس، تہٕ زِندٕ رودمُت۔\n15.\\tتہٕ أمِس اوس یہ طاقت زِ سُہ دِیہِ درندٕ سٕنزِ شکلہِ زِندٕ دِنہٕ، تہٕ یُس نہٕ درندٕ سٕنزِ شکلہِ ہٕنز پوجا کرِ، تِم گژھن مارنہٕ یِن۔ {زندگی: Gr. breath}\n16.\\tتہٕ سُہ چُھ سارنٕے لوکٕٹۍ تہٕ بٔڈۍ، امیر تہٕ غریب، آزاد تہٕ بندھن ہٕندِس دٔچھنِس اتھس منز، یا تِہندِس ڈیکس پیٹھ اکھ نشان حٲصل کرنُک سبب بناوان: {وصول کرنہٕ خٲطرٕ: Gr. تمن دِنہٕ خٲطرٕ}\n17.\\tتہٕ یہ زِ کانہہ تہِ انسان ہیکہِ نہ ہینہ تہٕ کٕنِتھ، سوائے تٔمِس سٕندِس نِشانہٕ، یا درندٕ سُند ناو، یا تٔمۍ سٕندِس ناوُک نمبر آسہِ۔\n18. یِہ چُھ حکمت۔ یُس سمجھ آسہِ سُہ درندٕ سُند تعداد گٔنزراوُن، تکیازِ یہِ چُھ انسان سُند تعداد۔ تہٕ تٔمۍ سُند نمبر {is} شیہ ہتھ تریہ {تہٕ} شے۔","1.\\tتہٕ میہ وُچھ تہٕ وُچھمُت اکھ کۅکرِ کۅکرِ سیون پہاڑس پیٹھ کھڑا، تہٕ أمِس سٍتـ̡ ژتٲجی ژور ساس، تہٕ تٔمِس سٍتـ̡ اوس مٲلہِ سُند ناو لیکھِتھ تہٕ تِمن ہٕندِس ڈیکس پیٹھ لیکھِتھ اوس۔\n2. تہٕ مے بوز آسمانہٕ پیٹھہٕ اکھ آواز، یِتھ زن واریہن آبن ہٕنز آواز، تہٕ أکِس بٔڈِ گجگرٕچ آواز: تہٕ مے بوز ہارپرن ہٕنز آواز یِمن ہٕندِس ہارپَس سٍتـ̡ گٔژھِتھ ٲس:\n3.\\tتہٕ تِمو گیوٚو تختس برونہہ کُن تہٕ ژۅن درندن تہٕ بزرگن برونہہ کُن اکھ نۆو گیون: تہٕ کانہہ تہِ انسان ہیوٚک نہٕ یہِ بٲتھ ہیچھِتھ مگر ہتھ ژتٲجی تہٕ ژور ساس، یِم زمینہٕ منزٕ نجات دِنہٕ آیہ۔\n4. یِم چھِ تِم یِم زنانن سٍتۍ ناپاک گٔمٕتۍ چھِ۔ تِکیازِ تِم چھِ کُنوارِ۔ یِم چھِ تِم یِم کُنہِ تہِ یِم آیہ انسانن منزٕ نجات دِنہٕ، خدایہ سٕندِ خٲطرٕ تہٕ دامن ہٕندِ خٲطرٕ گۅڈنِچ پھل۔ {redeemed: Gr. bought}\n5.\\tتہٕ تہندِس ٲسس منز آو نہٕ کانہہ فریب لبنہٕ، تکیازِ تِم چھِ خدایہ سٕندِس تختس برونہہ کُن بے عیب ۔\n6. تہٕ مے وُچھ بیاکھ فرشتہ آسمانس مَنٛز وُڑان، یُس تِمن زمینس پیٹھ روزن وٲلِس تہٕ پرٮ۪تھ قومس تہٕ رشتہٕ دارن تہٕ زبانہِ تہٕ لُکن ہٕنز تبلیغ کرنہٕ خٲطرٕ ابدی انجیل ٲس۔\n7. بَڑِ آوازِ سٍتـ̡ وَنُن، خدایہِ سُند خوف کرُن تہٕ تٔمِس جلال دِیُن۔ تٔمۍ سٕندِس قیامُک وقت چُھ آمُت، تہٕ تٔمِس سٕنز عبادت کٔرِو یٔمۍ آسمان، زمین، سمندر، تہٕ آبٕکۍ چشمہٕ بنوو۔\n8. تہٕ اَتھ پَتہٕ آو بیاکھ فرشتہٕ یُس وَنُن زِ بابل گۆو پیوٚو، سُہ بٔڈ شہر، تکیازِ تٔمۍ دِژ سارنٕے قومن پننہِ زناکٲری ہٕندِ قہر سٍتـ̡ شراب۔\n9.\\tتہٕ تریم فرشتہ ووت تِمن پَتہٕ بَڑِ آوازٕ سٍتـ̡ وونُن، یێلہِ کانہہ انسان درندٕ سٕندِس تہٕ تٔمۍ سٕنزِ شکلہِ ہٕنز پوجا کرِ، تہٕ تٔمِس ڈٮ۪کہٕ پٲٹھـ̡ یا اتھس مَنٛز نشانہٕ رٔٹِتھ\n10.\\tیۅہے گژھہِ خدایہ سٕندِ قہر سٕندِ شرابُک شراب، یُس تٔمۍ سٕندِس غصہٕ کِس پیالس مَنٛز رٔلِتھ رٔلِتھ تراونہٕ یِوان چھُ۔ تہٕ یِیہِ سُہ مقدس فرشتن ہٕنزِ موجودگی منز تہٕ کۅکرِ ہٕندِس حٲضِرِ سٍتـ̡ نار تہٕ گندھمہٕ سٍتـ̡ عذاب دِنہٕ:\n11.\\tتہٕ یِمن ہٕندِس عذابُک دھواں چُھ ہمیشہٕ خٲطرٕ کھسان، تہٕ یِمن چُھنہٕ دۅہہٕ تہٕ رٲژ آرام آسان، یُس درندٕ تہٕ تٔمۍ سٕنزِ شکلہِ ہٕنز پوجا کران چُھ، تہٕ یُس تٔمۍ سٕندِس ناوُک نشان میلان چُھ۔\n12. یێہے چُھہ مقدسن ہُند صبر: یێتہِ چِھ تِم یِم خدایہِ سٕندِ حُکمن تہٕ عیسیٰ سُند ایمان تھاوان چِھ۔\n13.\\tتہٕ بوز میہ آسمانہٕ پیٹھٕ اکھ آواز یُس میہ ونان چُھ، لیکھِو، بابرکت {چھِ} تِم مُردٕ یِم یِم اَمہِ پتہٕ خداوند سٕندِس سٍتـ̡ مران چِھ: آ، روح چُھ ونان زِ تِم گژھن پننہِ محنتہٕ نِش آرام دِنہٕ۔ تہٕ تِہنز کٲم چھِ تِمن ہٕنز پیروی کران۔ {از پیٹھ...: یا، از تام چُھ روح القدس ونان، ہاں}\n14.\\tتہ میہ وچھ اکھ سفید، تہ اوٚبرس پیٹھ بِہتھ اوس انسان سٕندِس نیچوس ہیو بِہتھ، کلس پیٹھ اوس سۅنہرۍ تاج تہ اتھس منز اکھ تیز دٲرۍ۔\n15.\\tتہٕ بیاکھ فرشتہ دراو مندرٕ منز، یُس اوبرس پیٹھ بِہتھ اوسُس بٔڑِ آوازِ سٍتـ̡ وۆن، تہٕ لُٹُن، تکیازِ ژے لُٹُنُک وق چُھہ آمُت۔ تکیازِ زمینہِ ہند فصل چھہ پۅختہ۔ {پۄختہٕ: یا، خشک کٔرِتھ}\n16.\\tتہٕ یُس اوٚبرس پیٹھ بِہتھ اوس، سُہ اوس زمینس پیٹھ پننہِ دٲرِ منز تھپھ کٔرِتھ۔ تہٕ زمین آو لُٹنہٕ۔\n17.\\tتہٕ بێاکھ فرشتہ دراو مندرِ منزہ یُس اسمانس مَنٛز چُھ، أمِس تہِ اوس اکھ تیز دٲر تہِ۔\n18.\\tتہٕ بیاکھ فرشتہ دراو قربان گاہس منز، ییمِس نارس پیٹھ اختیار اوس۔ تہٕ کٔرٕن تٔمِس تیز دٲرِ ہٕندِس کُنہِ تکیازِ تٔمۍ سٕندِ انگور چھِ پوٗرٕ پٲٹھۍ۔\n19.\\tتہٕ فرشتہٕ ترووُن پننہِ دٲرِ منز زمینہِ منز، تہٕ کٔرٕن زمینہِ ہٕنز انگور جمع کٔرِتھ خدایہ سٕندِس قہر کِس بٔڈِس شرابس مَنٛز۔\n20.\\tتہٕ شرابُک پریس آو شہرٕ ورٲے لَگنہٕ، تہٕ شرابٕ کِس دباونہٕ منزٕ دراو خوُن، حتیٰ کہ گُرِ ہٕنزِ لٔگِس تام، ساس تہٕ شیہ ہتھ فرلانگ ہٕندِس وقفس سٍتۍ۔","1. تہٕ وُچھ اسمانس مَنٛز بیاکھ نشانہٕ، عظیم تہٕ حیرت انگیز، سَتھ فرشتہٕ یِمن سَتھ ٲخری آفت آسہِ۔ تِکیازِ تِمن مَنٛز چُھ خدایہِ سُند قہر بٔرِتھ۔\n2.\\tتہٕ میہ وُچھ یُس شیشہِ ہُند سوٚدرٕ یُس نارس سٍتـ̡ رٔلِتھ اوس، تہٕ یِمو أمِس درندس پیٹھ فتح حٲصل کٔرمٕژ ٲس، تہٕ تٔمۍ سٕندِس ناوس پیٹھ تہٕ تٔمۍ سٕندِس ناوس پیٹھ فتح حٲصل کٔرمٕژ ٲس، تہٕ تٔمۍ سٕندِس ناوس ہٕندِس تعدادس پیٹھ، چِھہ شیشہٕ کِس سمندرس پیٹھ کھڑا، یتھ سٍتـ̡ خدایہ سٕندِ ہارپ ٲس۔\n3. تہٕ تِم چھِ موسیٰ سُند گٮ۪وُن، یُس خدایہِ سُند خادم چھُ، تہٕ کۅکرِ سُند نغمہٕ گٮ۪وان چھُ، یێلہِ چُھہ تُہند کٲم عظیم تہٕ حیرت انگیز ، خداوند قادر مطلق۔ عادل تہٕ پٔزۍ چھِہ تُہند طریقہٕ، اے مُقدسن ہُند بادشاہ۔ {سنت: یا، قوم، یا، عمر}\n4. اے خداوند، کُس کرِ نہٕ تۅہہِ کھوژُن تہٕ چانہِ ناوٕچ حمد کرِ؟ کیازِ {تو} چُھہ صرف {آرٹ} مقدس: تکیازِ سارِنٕے قومن یِن تہٕ تۅہہِ برونہہ کُن عبادت کرنہٕ؛ تِکیازِ تُہند فٲصلہٕ چھُ ظٲہِر سپدان۔\n5. تہٕ اَمہِ پَتہٕ وُچھمُت تہٕ وُچھمُت اسمانس مَنٛز گوٲہی ہٕندِس خیمہ ہُند مندر کھولنہٕ:\n6. تہٕ سَتھ فرشتہٕ دراو مندرٕ منز، سَتھ آفت ہیتھ ، خالص تہٕ سفید کُن لٲگِتھ تہٕ تِمن ہٕندِس سینس سٍتـ̡ سنہٕ سٕندِ پٔرِتھ لٲگِتھ ۔\n7. تہٕ ژۄن درندَو منزٕ دِژ أکۍ سَتھ فرشتن خدایہ سٕندِ قہر سٍتـ̡ بٔرِتھ سَتھ سۄنہٕ شیشہٕ، یُس ہمیشہٕ زندٕ روزان چُھ۔\n8.\\tتہٕ مندر اوس خدایہ سٕندِ جلال تہٕ تٔمۍ سٕندِ طاقتہٕ سٍتـ̡ دھوکہٕ سٍتـ̡ بٔرِتھ بٔرِتھ۔ تہٕ ہیوٚک نہٕ کانٛہہ تہِ انسان ہیکِس مندرس منٛز اژِتھ، یوٚتام نہٕ ستن فرشتن ہٕندۍ ستھ آفت پوٗرٕ گٔیہِ۔","1. تہٕ بوز میہ مندر منزٕ اکھ بٔڈ آواز یتھ منز ستن فرشتن وونُن زِ پَنٕنۍ وتہٕ گژھِو تہٕ خدایہ سٕندِ قہر ہٕنزِ شیشہٕ ترٲوِن زمینس پیٹھ۔\n2. تہٕ گۅڈنِچ گٔژھ تہٕ ترووُن پنٕنۍ شیشہ زمینس پیٹھ۔ تہٕ تِمن نفرن پیوٚو اکھ خوفناک تہٕ خوفناک زخم یمن پیٹھ درندٕ سُند نشان اوس، تہٕ تمن پیٹھ یِم تٔمۍ سٕنزِ شکلہِ ہٕنز پوجا کران ٲسۍ۔\n3. تہٕ دوٚیم فرشتہٕ تروو سمندرس پیٹھ پنٕنۍ شیشہ۔ تہٕ یہ بنیوو أکِس مردٕ سٕندِس خونس ہٕندۍ پٲٹھۍ: تہٕ پرٮ۪تھ کانہہ زندٕ روح موٗد سمندرس منز۔\n4. تہٕ تریمہِ فرشتن تروو پنٕنۍ شیشی دریاوَن تہٕ آبہٕ کین چشمن پیٹھ۔ تہٕ تِم بنییہِ خون۔\n5. تہٕ مے بوز آبُک فرشتہٕ وَنُن، اے خداوند، تہٕ یُس چُھ، تہٕ چُھہ تہٕ آسُن، کیازِ ژے چُھ یِتھُے فٲصلہٕ کورمُت۔\n6. تِمو چُھ مُقدسن تہٕ پیغمبرن ہُند خوُن تروومُت، تہٕ توے چُھکھ تِمن چنہٕ خٲطرٕ خوُن دِژمُت۔ تکیازِ تم چھہِ لایق۔\n7. تہٕ بوز میہ بیاکھ اکھ قربان گاہ منزہ ونان، یێلہِ تہِ چُھہ تُہند فیصلہٕ، یێلہِ تہِ چُھہ خداوند قادر مطلق، پزر تہٕ راستباز۔\n8.\\tتہٕ ژوٗرمہِ فرشتن تروو آفتابس پیٹھ پنُن شیشہ۔ تہٕ أمِس آو نار سۭتۍ نفرن زالنہٕ خٲطرٕ طاقت دِنہٕ۔\n9.\\tتہٕ انسان گٔیہِ سٮ۪ٹھاہ گرمی سٍتـ̡ دزنہٕ، تہٕ کٔرٕکھ خدایہ سٕندِس ناوٕچ بے عزتی یُس یِمن آفتن پیٹھ اختیار چُھ، تہٕ تِمو کٔر نہٕ تس جلال دِنہٕ خٲطرٕ توبہٕ۔ {دزنہٕ: یا، دزنہٕ}\n10. تہٕ پوٗنٛژمہِ فرشتن تروو پنٕنۍ شیشی درندٕ سٕنزِ نشستس پیٹھ۔ تہٕ تٔمۍ سٕنٛز سلطنت ٲس انہِ گٹہٕ سۭتۍ بٔرِتھ۔ تہٕ تِمو کٔر دَگ خٲطرٕ پنٕنۍ زبان گٔژِھتھ،\n11.\\tتہٕ کٔرٕن آسمانہٕ کِس خدایس تِہندِ دَگ تہٕ دَگ کِنۍ کفر تہٕ تِہندِ کامہِ سٍتـ̡ کٔرٕن نہٕ توبہٕ۔\n12. تہٕ شیٚیِم فرشتن تروو پنٕنۍ شیشی دریائے فرات کِس بٔڈِس دریاوَس پیٹھ۔ تہٕ امیک آب آو خشک کرنہٕ، تاکہ مشرقک بادشاہن ہٕنز وتھ گژھہٕ تیار۔\n13.\\tتہٕ وُچھ میہ تریہ ناپاک روحہٕ نِلہٕ نِش اژان تہٕ درندٕ سٕندِ ٲسہِ منزٕ تہٕ اپُز پیغمبر سٕندِ ٲسہِ منز۔\n14. تِم چِھ شیطانن ہٕندِ روحہٕ سٍتـ̡ معجزات کَران، {یُس} زمینہٕ تہٕ سارِنٕے دُنِیاہٕکِس بادشاہن نِش نیران چُھ، تِمن خدایہ تعالیٰ سٕندِس تتھ عظیم دۅہہٕ کِس جنگس مَنٛز جمع کرنہٕ خٲطرٕ۔\n15.\\tوُچھ، بہٕ چھُس ژوٗر سٍتۍ آمُت۔ سُہ چُھ بابرکت یُس وچھان چُھ، تہٕ پَنُن پلو تھاوان چُھ، یُس نہٕ سُہ ننگہٕ پکان چُھ، تہٕ تِم وُچھن تٔمۍ سٕنز شرم وُچھان۔\n16.\\tتہٕ تٔمۍ کٔر تِم أکِس جایہِ یَتھ عبرانی زبانہِ مَنٛز آرماگیڈن ونان چھِ۔\n17. تہٕ سٔتِم فرشتن تروو پنٕنۍ شیشی ہوہس منٛز۔ تہٕ آسمانہٕ کِس مندرٕ منزٕ دراو تختہٕ پیٹھٕ اکھ بٔڈ آواز، یہِ چُھ کرنہٕ آمُت۔\n18.\\tتہٕ اَتہِ آسہٕ آوازٕ، تہٕ گجگر، تہٕ بجلی۔ تہٕ اتہِ آو اکھ زبردست زلزلہٕ، یُس نہٕ انسان زمینس پیٹھ اوس، یوتاہ زبردست زلزلہٕ، {تہٕ} یوتاہ عظیم۔\n19. تہٕ عظیم شہر آو ترٮ۪ن حصن مَنٛز تقسیم کرنہٕ، تہٕ قومن ہٕندِ شہر گٔیہِ پیوٚو: تہٕ عظیم بابل آو خدایہ سٕندِ برونہہ کُن یاد پاونہٕ، تہٕ تٔمِس دِنہٕ خٲطرٕ تٔمِس شرابُک پیالہ دِنہٕ۔\n20. تہٕ پرٮ۪تھ کانہہ جزیرٕ ژوٚل، تہٕ پہاڑ آو نہٕ لبنہٕ۔\n21.\\tتہٕ انسانس پیٛٹھ پیوٚو آسمانہٕ منزٕ اکھ بٔڈ ڈولہٕ، {پرٮ۪تھ کٔن} ہٕندِس وزنس سٍتـ̡ تہٕ انسانو کٔر خدایہ سٕندِ وبا سٍتـ̡ کُن کُفر کرنہٕ۔ تکیازِ امیک طاعون اوس واریاہ زیادہ۔","1. تہٕ سَتن فرشتو منزٕ آو اکھ یٔمِس سَتھ شیشہٕ ٲس، تہٕ کوٚرُن میہ سٍتـ̡ کتھ باتھ تہٕ وونُن یور یور ۔ بہٕ ہاوٕ ژے تٔمِس بٔڈِس طوائف سُند فیصلہٕ یُس واریاہن آبن پیٹھ بِہتھ چُھ:\n2. یٔمِس سٍتـ̡ زمینہٕ کٮ۪و بادشاہو زنا کٔرِمُت چُھ، تہٕ زمینہٕ کِس روزن وٲلِس سٍتـ̡ چُھ تٔمۍ سٕندِس زناکٲری ہٕندِس شرابہٕ سٍتـ̡ شرابہٕ سٍتـ̡ شرابہٕ سٍتـ̡ مست کرنہٕ آمُت۔\n3.\\tیێمہِ سٍتـ̡ نِیوو میہ روحہٕ سٍتـ̡ بیابانس مَنٛز، تہٕ وُچھ اَکھ زنانہٕ بِہِتھ أکِس سرخ رنٛگہٕ وٲلِس درندس پیٹھ بِہتھ، یێمِس سَتھ کلہٕ تہٕ داہ سینگ۔\n4. تہٕ زنانہٕ ٲس جامنی تہٕ سرخ رنگس منٛز سجاونہٕ آمٕژ، تہٕ سۄنہٕ تہٕ قیمتی پتھرو تہٕ موتیو سۭتۍ سجاونہٕ آمٕژ، تہٕ أمس اتھس منٛز اوس اکھ سۄنہٕ پیالہ یُس پننہٕ زناکاری ہٕنٛز ناپاکیزگی تہٕ گندگی سۭتۍ بٔرِتھ اوس: {سجاوٹ: Gr. gilded}\n5.\\tتہٕ تٔمۍ سٕندِس ڈیکس پیٹھ اوس اکھ ناو لیکھِتھ، اسرار، بابل عظیم، بدکارن تہٕ مکروہ زمینن ہٕنز موج۔ {بدکاری: یا، زناکاری}\n6. تہٕ مے وُچھ زنانہٕ مقدسن ہٕندِس خونس سٍتـ̡ تہٕ حضرت عیسیٰ سٕندِس شہیدن ہٕندِس خونہٕ سٍتـ̡ شرابس سٍتـ̡ شرابس سٍتـ̡ شرابہٕ۔\n7. تہٕ فرشتن ووٚن میہ زِ ژیہ کیازِ گٔیہِ حیران؟ بہٕ وَن ژے زنانہِ ہُند اسرار، تہٕ أمِس درندٕ سُند یُس أمِس رٔٹِتھ چھُ، یٔمِس سَتھ کلہٕ تہٕ داہ سینٛگ چھِ۔\n8. سُہ جانور یُس ژے وُچھمُت اوس، تہٕ چُھ نہٕ۔ تہٕ گژھن بونہٕ کھۅنہٕ منزٕ کھسِتھ تہٕ فنا گژھن: تہٕ یِم زمینس پیٹھ روزان چھِ تِم گژھن حیران، یِمن ہُند ناو چھُنہٕ زندگی ہٕنزِ کتابہِ منز لیکھنہٕ آمُت، ییلہ تِم سُہ جانور وُچھان یُس اوس، تہٕ چھُنہٕ تہٕ توتہِ چھُ۔\n9.\\tتہِ چھہ سہ ذہن یتھ منز حکمت آسہِ۔ سَتھ کلہٕ چھِ سَتھ پہاڑ، یَتھ پٮ۪ٹھ زنانہٕ بِہِتھ چھِ۔\n10. تہٕ ستھ بادشاہ چھہِ: پانژھ گٔیہِ، تہٕ اکھ چُھ، {تہٕ} بیٛاکھ چُھ نہٕ وُنیُک تام آمُت۔ تہٕ ییلہ سُہ یِوان چھُ، تٔمِس پزِ کم جاے جٲری تھاوُن۔\n11. تہٕ سُہ جانور یُس اوس، تہٕ چُھ نہٕ، سُہ تہِ چُھ ٲٹھم، تہٕ سَتَن مَنٛز چُھ، تہٕ چُھ فلاکَس مَنٛز گَژھان۔\n12. تہٕ یِم داہ سینگ یِم ژے وُچھمٕتۍ چھِ، تِم چھِ داہ بادشاہ، یِمن نہٕ وُنیُک تام کانہہ بادشاہت میلہِ۔ مگر بادشاہ سٕندِ حثیتہٕ کٔرِو اَکہِ گھنٹہٕ درندَس سٍتـ̡ طاقت حٲصِل۔\n13.\\tیِمن چُھ اکھ ذہن، تہٕ دِن پنُن طاقت تہٕ طاقت درندس دِنہٕ۔\n14.\\tیِم کٔرِن کۅکرِ سٍتـ̡ جنگ، تہٕ کۅکرِ کُنہِ کُنہِ سٍتـ̡ یێلہِ سٍتـ̡ سُہ چُھہ خداوند تہٕ بادشاہن ہُند بادشاہ تہٕ یِم أمِس سٍتـ̡ چُھہ بُلاونہٕ آمُت، تہٕ چُھہ یِمن سٍتـ̡ وفادار تہٕ چُھہ یِمن سٍتـ̡ بُلاونہٕ آمُت۔\n15.\\tتہٕ سُہ چُھ مےٚ ونان، یُس آب ژے وُچھان چُھ، یَتہِ طریٖقہٕ بِہِتھ چُھ، تِم چِھ لوُکھ، تہٕ بٔڑۍ، قومن تہٕ زبانہٕ۔\n16.\\tتہٕ یِم داہ سینگ یُس ژے درندس پیٹھ وُچھِو، تِم گژھن بدکار سٍتـ̡ نفرت، تہٕ کرِ أمِس ویران تہٕ ننگہٕ، تہٕ تٔمۍ سُند ماز کھٮ۪وان تہٕ نارٕ سٍتـ̡ زالنہٕ۔\n17.\\tکیازِ خداین چُھ تِہندِس دِلس مَنٛز پنٕنۍ مرضی پوٗرٕ کرنہٕ خٲطرٕ تہٕ رضامندی حٲصل کرنہٕ خٲطرٕ تہٕ پنٕنۍ بادشاہت درندَس دِنہٕ خٲطرٕ تھوومُت، یوتام نہٕ خدایہِ سُند کلام پوٗرٕ سپدِ۔\n18.\\tتہٕ سُہ زنانہٕ یُس ژے وُچھان چُھ، سُہ چُھ سُہ بٔڈ شہر، یُس زمینہٕ کِس بادشاہن پیٹھ راج کران چُھ۔","1. تہٕ یِمو چیزو پَتہٕ وُچھ میہ بیاکھ فرشتہ آسمانہٕ پیٹھٕ بۄن وسُن، یُس واریاہ طاقتور اوس۔ تہٕ زمین گٔیہِ أمۍ سٕندِ عظمتس سٍتۍ گاش۔\n2. تہٕ تٔمۍ ووٚن زورٕ آوازِ سٍتـ̡ وۆنُن، بابل عظیم گۆو پیوٚو، تہٕ سُہ چُھ شیطانن ہُند روزن جاے تہٕ پرٮ۪تھ کُنہِ بدکار روحُک تھپھ تہٕ پرٮ۪تھ ناپاک تہٕ نفرت کرن وول جاناوار سُند پنجرٕ بنیومُت۔\n3. تکیازِ سارِوٕے قومن چُھ أمِس سٍتـ̡ زناکاری ہٕندِس شرابُک شراب، تہٕ زمینہٕ کیو بادشاہو چُھ أمِس سٍتـ̡ زناکاری کٔرمٕژ، تہٕ زمینہٕ ہٕندِس سوداگر سٍتـ̡ چُھہ تٔمۍ سٕندِس لذیذن ہٕنزِ کثرت سٍتـ̡ امیر سپدان۔ {کثرت: یا، طاقت}\n4. تہٕ مے بوز آسمانہٕ پیٹھٕ بیاکھ آواز یتھ منز وونُن زِ اے میٲنۍ لوکو، یُتھ نہٕ تٔمۍ سٕندِس گۅنہن منز شریک گژھُن، تہٕ یێلہِ نہٕ تٔمۍ سٕندِس ععذابس سٍتـ̡ رٔٹِتھ تہٕ یێلہِ نہٕ تٔمۍ سٕندِس عَباہَس سٍتـ̡ میلہٕ۔\n5. تِکیازِ تٔمۍ سٕندِ گۅناہ چھِ جنتس تام وٲتِمٕتۍ، تہٕ خداین چُھ تٔمۍ سٕندِ گناہ یاد پٲٹھۍ۔\n6. تٔمِس دِیُن یُتھ تٔمۍ سُند انعام دِیُت، تہٕ تٔمۍ سٕندِ کامہِ مُطٲبق دِیُن أمِس دۄگنہٕ۔\n7. تٔمۍ کوتاہ چھے پانس جلال دِژمٕژ، تہٕ لذیذ زندگی بٔنِتھ، تیوٗت عذاب، غم تہٕ غم دِیُت، کیازِ سۄ چھے پننِس دِلس منز ونان زِ بہٕ چھے ملکہ بِہتھ، تہٕ بہٕ چھے نہٕ بیواہ تہٕ وُچھُن نہٕ کانہہ غم۔\n8.\\tتێلہِ گژھہِ تٔمۍ سٕنزِ وبا اکہِ دۅہہ، موت، ماتم تہٕ قحط۔ تہٕ سُہ گژھہِ نارٕ سٍتـ̡ دزنہٕ یُن: یێلہِ چُھہ خداوند خدا یُس أمِس انصاف کران چُھ۔\n9.\\tتہٕ زمینٕکۍ بادشاہ، یِمو زناکاری کٔرمٕژ تہٕ أمِس سٍتـ̡ لذیذ پٲٹھـ̡ روزان چِھ، تٔمِس سٍتـ̡ ماتم کٔرِن، تہٕ أمِس خٲطرٕ ماتم کٔرِن، یێلہِ تِم أمِس دزان وُچھن،\n10.\\tپننہِ عذابٕکہِ خوفہٕ سٍتـ̡ دوٗر کھڑا گٔژھِتھ وَنُن، افسوس، سُہ بٔڈ شہر بابل، سُہ طاقتور شہر! تکیازِ أکِس گھنٹس منز چُھ تُہند فیصلہٕ یِوان۔\n11. تہٕ زمینہِ ہٕندِس سوداگر رٔلِتھ تہٕ ماتم کٔرِن أمِس خٲطرٕ۔ تکیازِ کانہہ تہِ انسان چھہ نہ وۅنۍ تہند مال ہینہ یوان:\n12.\\tسۄنہٕ تہٕ رۄپھ تہٕ قیمتی پتھر، تہٕ موتی، تہٕ نفیس کُن، تہٕ واگن رنگہٕ، تہٕ ریشم، تہٕ سٲرۍسٕے لٔکرِ ہٕندِس بانہٕ، تہٕ سارِنٕے قٕسمٕکۍ بانہٕ، تہٕ سارِوٕے قٕسمٕکۍ داندٕکۍ بانہٕ، تہٕ پیتل تہٕ ششتٕر، تہٕ سنگ مرمرٕکۍ بانہٕ، {تھین: یا، مٔٹھۍ}\n13. تہٕ دالچنی، تہٕ خوشبو، تہٕ مرہم تہٕ لوبان تہٕ شراب، تہٕ تیل، تہٕ عمدہ آٹ، تہٕ کٕنٕک، تہٕ جانور، تہٕ کٹہٕ، تہٕ گُرۍ، تہٕ رتھ، تہٕ غلام تہٕ انسانن ہٕنٛز روح۔ {غلام: یا، لاشہٕ}\n14.\\tتہٕ یِم پھل تۅہہِ نِش رٔلِتھ چھِ، تہٕ یِم سارِنٕے چیٖز یِم لٔبِتھ تہٕ اصل ٲسِتھ چھِ، تہٕ یِم نہٕ وُنہٕ تہِ لٔبِتھ تہٕ یِم تہِ میلہِ نہٕ۔\n15.\\tیِمن چیزن ہٕندِ سوداگر، یِم أمِس امیر بنٲومٕتۍ، تِمن ہٕندِس عذابٕکہِ خوفہٕ سٍتـ̡ رودُن تہٕ وُپھ کٔرِتھ،\n16.\\tتہٕ وَنُن، افسوس، سُہ بٔڈ شہر، یُس عمدہ کُنہِ تہٕ واگن رنگہٕ تہٕ سرخ رنگہٕ لٲگِتھ اوس، تہٕ سۄنہٕ سٍتـ̡ سٍتـ̡ سجاونہٕ آمُت، تہٕ قیمتی پتھرٕ تہٕ موتیو سٍتـ̡ سجاونہٕ آمُت۔\n17. تکیازِ أکِس گھنٹس منز چُھ یُتھ بٔڈ دولت ختم سپدان۔ تہٕ پرٮ۪تھ جہازُک ماسٹر، تہٕ جہازن ہٕنز سٲری کمپنی، تہٕ جہازٕ تہٕ سمندرٕ کِس تجارتس منز سارِوٕے کمپنی، تہٕ سمندرٕ کِس سفرس منز تِمن ہٕندِس تجارتس سٍتـ̡ روٗدۍ،\n18.\\tتہٕ رووُن ییلہ تِمو أمِس دزُن وُچھِتھ وُچھِتھ وَنُن زِ یَتھ بٔڈِس شہرس کُس چُھہ شہر!\n19.\\tتہٕ تِمو ترٲو پننِس کلَس پیٹھ گرد، تہٕ وَنُن وُنُن، ہاے ہاے سُہ بٔڈ شہر، یَتھ مَنٛز سمندرس مَنٛز جہازٕ آسنہٕ کِنۍ سارِنٕے امیر بنیومُت چھُ۔ تکیازِ أکس گھنٹس منز چھیہ سۅ ویران گژھان۔\n20. تٔمِس سٍتـ̡ کرو جنت، تہٕ {یێہ} مقدس رسولن تہٕ پیغمبرن سٍتـ̡ خوش گژھُن۔ تکیازِ خداین چُھ تٔمِس سٍتـ̡ انتقام۔\n21. تہٕ أکۍ طاقتور فرشتہٕ تُل اکھ بٔڈ ملہٕ کٔنہِ ہیوٗ کٔنہِ، تہٕ ترٛٲوُن سمندرس مَنٛز، تہٕ وونُن زِ یِتھٕ پٲٹھۍ یِیہِ سُہ عظیم شہر بابل یِیہِ تشددٕ سٍتـ̡ ؤسِتھ تراونہٕ، تہٕ یِہ یِہ نہٕ لبنہٕ یِنہٕ۔\n22. تہٕ ہارپرن، موسیقارن، تہٕ پایپرن تہٕ ٹرمپٹن ہٕنز آواز گژھہِ نہٕ توے منز بالکل تہِ بوزنہٕ۔ تہٕ کُنہِ تہِ دستکٲری ہُند کانہہ تہِ کاریگر ییہ نہٕ توے منز لبنہٕ۔ تہٕ ژے منز گژھہِ نہ گٹہِ ہٕنز آواز بوزنہٕ۔\n23. تہٕ شمعُک گاش گژھہِ نہٕ توے سٍتـ̡ تہٕ یێلہِ تہِ چمکان۔ تہٕ مہرازٕ تہٕ مہرنہِ ہٕنٛز آواز گژھہِ نہٕ ژےٚ منٛز بوزنہٕ یِنہٕ: تِکیازِ تُہٕنٛدِ سوداگر ٲسۍ زمینٕکۍ عظیم نفر۔ تکیازِ تۅہہِ سٍتۍ آیہ سارنٕے قومن دھوکہٕ دِنہٕ۔\n24.\\tتہٕ أمِس مَنٛز اوس پیغمبرن تہٕ مقدسن ہُند تہٕ زمینس پیٹھ مارنہٕ آمٕتۍ سارِنٕے سُند خون لبنہٕ آمُت۔","1.\\tتہٕ یِمو کتھٕ پَتہٕ بوز میہ آسمانس منز واریاہن لُکن ہٕنز اکھ بٔڈ آواز، یُس وَنُن چھُ، الیلویا۔ نجات تہٕ جلال تہٕ عزت، تہٕ طاقت، خداوند سانہِ خدایہ سٕندِ خٲطرٕ:\n2. پٔزۍ تہٕ نیک سٍتـ̡ چُھہ تٔمۍ سٕندِس فٲصلس سٍتـ̡ یێمہِ سٍتـ̡ بٔڈِس طٲیفس سٍتـ̡ فٲصلہٕ کورمُت، یٔمۍ پننہِ زناکاری سٍتـ̡ زمینس فاسد کٔرِتھ تہٕ پننین خدمتگارن ہُند خونُک انتقام کورمُت۔\n3. تہٕ بییہِ وون تِمو الیلویا۔ تہٕ تٔمۍ سُند دھواں ووٚتھ ہمیشہٕ خٲطرٕ۔\n4.\\tتہٕ ژور وُہ بُزرگ تہٕ ژۅشوٕے جانور پیوٚو تہٕ کٔرٕکھ تختس پیٹھ بِہتھ خدایہ سٕنز عبادت کٔرِتھ وَنُن آمین۔ الیلویا۔\n5.\\tتہٕ اَکھ آواز دراو تختہٕ پیٹھ، یێلہِ وونُن زِ سٲنـ̡ خدایہِ سٕندِس سارِنٕے خادمَن، تہٕ یێمہِ سٕندِس سارِنٕے بٔڈِس سٍتـ̡ س�\n6. تہٕ مے بوز یِتھٕ پٲٹھۍ یہِ أکِس بٔڈِس بٔڈِس ہٕنزِ آواز، تہٕ واریاہن آبن ہٕنزِ آوازٕ، تہٕ زوردار گرٛیٚہنٕچ آوازٕ، یُس وَنُن چُھ، Alleluia: یێلہِ خداوند قادر مطلق بادشاہت چُھ۔\n7. أسۍ گژھو خۅش تہٕ خۅش گژھُن، تہٕ أمِس عزت دِیُن: تکیازِ کۅکرِ ہُند خانٛدر آو تہٕ تٔمۍ سٕنزِ زنانہِ چھے پانس تیار کٔرمٕژ۔\n8.\\tتہٕ أمِس آو عطا کرنہٕ زِ سُہ گژھہِ نفیس کُن لٲگِتھ، صاف تہٕ سفید، تکیازِ اصل کُن چھُ مقدسن ہٕنز نیکی ۔ {سفید: یا، روشن}\n9.\\tتہٕ سُہ چُھہ میانہِ خٲطرٕ ونان، لیکھِو، بابرکت {چھِ} تِم یِم کۅکرِ سٕندِس کھاندرس منز بُلاونہٕ آمٕتۍ چھِ۔ تہٕ سُہ چُھ مےٚ ونان، یِم چھِ خدایہِ سٕنز پٔزۍ کتھ ۔\n10.\\tتہٕ بہٕ پیوٚو تٔمۍ سٕندِس قدمن پیٹھ۔ تہٕ تٔمۍ ووٚن میہ وُچھ، وُچھو نہٕ تُہُند سٲتھی تہٕ تُہند بٲے یِمن عیسیٰ سٕنز گوٲہی چِھ: خدایہِ سٕنز عبادت کٔرِو: کیازِ عیسیٰ سٕنز گوٲہی چِھ پیشن گویی ہُند روح۔\n11. تہٕ وُچھ اسمانس یلہٕ تہٕ وُچھ اکھ سفید گُرۍ۔ تہٕ یُس أمِس پیٹھ بِہتھ اوس سُہ وفادار تہٕ پٔزۍ وننہٕ آمُت، تہٕ نیکی سٍتـ̡ چُھ سُہ فیصلہ کران تہٕ جنگ کران۔\n12.\\tتٔمۍ سٕنزِ أچھ آسہٕ نارٕچ نار ہٕندۍ پٲٹھۍ، تہٕ تٔمۍ سٕندِس کلس پیٹھ ٲسۍ واریاہ تاج۔ تہٕ أمس اوس اکھ ناو لیکھمُت، یُس نہ کٲنسہ انسانس پتاہ اوس، مگر سُہ اوس پانہٕ۔\n13.\\tتہٕ تس اوس خونس سٍتـ̡ پوشاک لٲگِتھ تہٕ تٔمِس ناوُک ناو چُھ خدایہ سُند کلام وننہٕ یوان۔\n14.\\tتہٕ یِم لشکر آسمانس منز ٲسۍ، سفید تہٕ صاف ستھرٕ لٲگِتھ سفید گُرٮ۪ن پیٹھ لٔگِتھ أمِس پَتہٕ پَتہٕ۔\n15.\\tتہٕ تٔمۍ سٕندِ ٲسہِ منزٕ دراو اکھ تیز تلوار، یُتھ سُہ قومن پیٹھ مار دِیہ، تہٕ سُہ کرِ ششتٕرِ ہٕنزِ لٔرِ سٍتـ̡ تِمن پیٹھ حکوٗمت، تہٕ سُہ چُھ خدایہ سٕندِ شدتہٕ تہٕ قہر سٍتـ̡ شرابہٕ کٔرِتھ۔\n16.\\tتہٕ أمِس چُھس لباسس تہٕ رانس پیٹھ اکھ ناو لیکھِتھ، بادشاہن ہُند بادشاہ، تہٕ لارڈ آف لارڈز۔\n17. تہٕ مے وُچھ اکھ فرشتہ آفتابس منز کھڑا ۔ تہٕ تٔمۍ ووٚن بَڑِ آوازِ سٍتۍ، یِم سارِنٕے جاناوارن آسمانس منز وُڑان چھِ، یِمو تہٕ پَنُن پان جمع کٔرِو عظیم خدایہ سٕندِس کھٮ۪نہٕ خٲطرٕ۔\n18.\\tیُتھ تُہۍ بادشاہن ہُند ماز تہٕ کپتانن ہُند ماز تہٕ طاقتور نفرن ہُند ماز تہٕ گُرٮ۪ن ہُند ماز تہٕ یِمن پیٹھ بِہتھ روزن والٮ۪ن ہُند ماز تہٕ سارنٕے انسانن ہُند ماز کھیوٚو۔\n19. تہٕ مے وُچھ درندٕ تہٕ زمینٕکۍ بادشاہ تہٕ تِہٕندِس لشکر گُرِس پیٹھ بِہتھ أمِس خٕلاف تہٕ تٔمۍ سٕندِس فوجس خٕلاف جنگ کرنہٕ خٲطرٕ جمع گٔیہِ۔\n20.\\tتہٕ أمِس سٍتـ̡ آو سُہ اپُز پیغمبر یُس أمِس برونہہ کُن معجزات کٔرِتھ، ییمہِ سٍتـ̡ تِمن دھوکہٕ دِنہٕ آمُت یِمن درندٕ سُند نِشانہٕ حٲصِل اوس تہٕ تِم یِم تٔمۍ سٕنزِ شکلہِ ہٕنز پوجا کران ٲسۍ۔ یم دۅشوے آیہ نار کس جھیلس منز زِندٕ تراونہ۔\n21. تہٕ باقٕے گُرِ سٕنزِ تلوار سٍتـ̡ مارنہٕ یُس گُرِس پیٹھ بِہتھ اوس، یُس {تلوار} تٔمۍ سٕندِس ٲسس منزٕ دراو تہٕ سارِنٕے جاناوار گٔیہِ تِہٕندِس مازس سٍتـ̡ بٔرِتھ۔","1. تہٕ مے وُچھ اکھ فرشتہ آسمانہٕ پیٹھٕ بۄن ووس، یٔمِس اتھس منز بونہٕ روٚس کھۅڈٕچ کُنز تہٕ اکھ بٔڈ زنجیر ٲس۔\n2. تہٕ تٔمۍ تھپھ کٔرِتھ ڈریگن، سُہ پرون ناگ، یُس شیطان تہٕ شیطان چُھ، تہٕ ساس ؤری بند،\n3.\\tتہٕ ترٛٲوِن سُہ بٔنِس کھۄدِس مَنٛز، تہٕ بند کٔرِتھ تھٲوِن أمِس مُہر تہٕ ساس ؤری پوٗرٕ گژھن تام قومن دھوکہٕ دِنہٕ یُن، تہٕ تمہ پتہٕ گژھہِ سُہ رژھ\n4. تہٕ مے وُچھ تخت تہٕ تِم بِہتھ تہٕ تِمن ہُند فیصلہ آو دِنہٕ۔ تہٕ {مے} وُچھ تِمن ہٕندِ روحہٕ یِم عیسیٰ سٕنزِ گواہی خٲطرٕ تہٕ خدایہ سٕندِ کلامٕ خٲطرٕ کلہٕ ژٹنہٕ آمٕتۍ ٲسۍ، تہٕ یِمو نہٕ درندٕچ پوجا ٲس کٔرمٕژ، تہٕ نہ تٔمۍ سٕنزِ شکلہٕ سٍتـ̡ تہٕ تِمن ہٕندِس ڈٮ۪کہٕ پٲٹھـ̡ تہٕ تِمن ہٕندِس اَتھن مَنٛز اوس تٔمۍ سٕندِس نِشانہٕ سٍتـ̡ آمُت کرنہٕ۔ تہٕ تِمو رودۍ ساس ؤری مسیحس سٍتـ̡ زندٕ تہٕ بادشاہی۔\n5.\\tمگر باقٕے مُردٕ رودۍ نہٕ ساس ؤری ختم گژھنس تام زندٕ۔ یہِ {چھُ} گۄڈنِچ قیامت۔\n6. بابرکت تہٕ پاک سُہ چُھہ یُس گۄڈنِکِس قیامتس مَنٛز حصہ آسہِ: یِتھِس دٔیمِس مرنس پیٹھ چُھنہٕ کانہہ طاقت آسان، مگر تِم گژھن خدایہ تہٕ مسیح سٕندِ پادٕرۍ تہٕ تس سٍتـ̡ ساس ؤری بادشاہت کرنہٕ۔\n7. تہٕ ییلہِ ساس ؤری ختم گژھِ، شیطان ییہِ قٲد خانہٕ منزٕ نیبر نیرنہٕ،\n8.\\tتہٕ نیرِ تِمن قومن دھوکہٕ دِنہٕ خٲطرٕ یِم زمینہِ ہٕندِس ژۄن ژۅن ژۅن حصن مَنٛز چھِ، گوگ تہٕ ماگوگ تہٕ یِمن ہُند تعداد سمندرٕچ سیکہِ ہیوٗ چھُ۔\n9.\\tتہٕ تِم گٔیہِ زمینہِ ہٕندِس کُنہِ پٲٹھۍ، تہٕ گٔیہِ مُقدسن ہٕندِس خٲمس تہٕ پیاری شہرس اندۍ پٔکھۍ، تہٕ دِژ خدایہِ سٕندِ طرفہٕ نار آسمانہٕ منزٕ تہٕ کھیوٚکھ تِم کھٮ۪نہٕ۔\n10.\\tتہٕ یُس شیطان یُس تِمن دھوکہٕ دِژ، سُہ آو نار تہٕ گندھک جھیلس مَنٛز تراونہٕ، یتہِ درندہ تہٕ اپُز پیغمبر چھِ، تہٕ یِم روزِ دۅہ تہٕ رٲژ ہمیشہٕ خٲطرٕ عذاب۔\n11. تہٕ وُچھ میہ اکھ بوٚڈ سفید تخت، تہٕ یُس اتھ پیٹھ بِہتھ اوس، یٔمۍ سٕندِ بُتھِ نِش زمین تہٕ آسمان ژٔلِتھ ژٔلۍ۔ تہٕ تمن خٲطرٕ ٲس نہٕ کانہہ جاۓ لبنہٕ۔\n12. تہٕ مے وُچھ مُرد، لۄکٕٹۍ تہٕ بٔڈ، خدایہ سٕندِ برونہہ کُن کھڑا ۔ تہٕ کتابہٕ آیہ کھولنہٕ: تہٕ بیاکھ کتاب آیہ کھولنہٕ، یۄسہٕ زندگی ہٕنز کتابہٕ چھےٚ: تہٕ مرن ہُند فیصلہ آو تمن چیزن سٍتۍ کرنہٕ یِم کتابن منز لیکھنہٕ آمٕتۍ ٲسۍ۔\n13.\\tتہٕ سمندرَن دِژ مُردٕ یِم اتھ منز ٲسۍ۔ تہٕ موت تہٕ جہنم کٔر تِمن منز موجود مُردٕ تہٕ تِمن ہُند فیصلہ آو پرٮ۪تھ أکِس انسانس تہندِ کامہِ مطٲبق کرنہٕ۔ {جہنم: یا، قبر}\n14.\\tتہٕ موت تہٕ جہنم آو نار کِس جھیلس منز تراونہٕ۔ یہِ چھُ دوٚیِم موت۔\n15. تہٕ یُس نہٕ زندگی ہٕندِس کتابہِ مَنٛز لیکھِتھ لبنہٕ آو، سُہ آو نارٕ کِس جھیلس مَنٛز تراونہٕ۔","1. تہٕ وُچھ میہ اکھ نۆو آسمان تہٕ اکھ نٔو زمین، تکیازِ گۅڈنِچ آسمان تہٕ گۅڈنِچ زمین گٔیہِ۔ تہٕ بییہٕ اوس نہٕ کنہہ سمندر۔\n2. تہٕ میہ وُچھ یوحنا مقدس شہر، نۆو یروشلم، یُس خدایہِ سٕندِ طرفہٕ آسمانہٕ پى۪ٹھہٕ وسان اوس، یُس پننِس خانٛدارس خٲطرٕ سجاونہٕ آمٕژ مہرنہِ ہٕندِس طورس پیٹھ تیار اوس۔\n3. تہٕ مے بوز آسمانہٕ منزٕ اَکھ بٔڈ آواز یێلہِ وۆن، وُچھو، خدایہِ سُند خیمہ {چُھ} انسانن سٍتـ̡ تہٕ سُہ روزِ تِمن سٍتـ̡ تہٕ تِمن سٍتـ̡ روزُن، تہٕ خدا آسہِ تِمن سٍتـ̡ تِمن سٍتـ̡ خدا۔\n4. تہٕ خدا کرِ تِہٕنزِ أچھن منزٕ سارِنٕے اوٚش صاف کرنہٕ۔ تہٕ بییہِ گژھہِ نہ موت، نہ غم، نہ روُن، نہ گژھہِ بییہ کانہہ دگ: تکیازِ گۅڈنِکۍ چیز چھہِ گزرۍمٕتۍ۔\n5.\\tتہٕ یُس تختس پیٹھ بِہتھ اوس، ووٚن زِ وُچھ، بہٕ چھُس سارِنٕے چیزن نوو بناوان۔ تہٕ تٔمۍ ووٚن مے لیٚکھِو: یِم لفظ چھِ پٔز تہٕ وفادار۔\n6. تہٕ تٔمۍ ووٚن میہ زِ یہ چُھ سپدان۔ بہٕ چھُس الفا تہٕ اومیگا، آغاز تہٕ اختتام۔ بہٕ دِیہ تس یُس زندگی ہٕندِس آبہٕ کِس چشمہٕ سٍتـ̡ آزاد آسہِ۔\n7. یُس غالب سپدِ، سُہ گژھہِ سارِنٕے چیزن ہُند وٲرث۔ تہٕ بہٕ بنہٕ تٔمۍ سُند خدا، تہٕ سُہ آسہٕ میون نیٚچُو۔ {سٲری چیز: یا، یم چیز}\n8.\\tمگر خوفزد، کافر، تہٕ مکروہ تہٕ قاتل، تہٕ بدکار تہٕ جادوگر، تہٕ مشرک تہٕ سارِنٕے اپُز، یُس نار تہٕ گندھک سٍتۍ دزان چھُ، یُس دوٚیِم موت چھُ۔\n9.\\tتہٕ سَتَو فرشتو منزٕ آو میہ نِش اکھ یٔمِس سَتھ ٲخری طاعون سٍتـ̡ بٔرِتھ سَتھ شیشہٕ آسہٕ، تہٕ کٔرٕن میہ سٍتـ̡ کتھ باتھ کٔرِتھ وونُن، یێلہِ بہٕ ہٲوِتھ ژے مہرِنہِ، کۅکرِ سٕنزِ زنانہٕ۔\n10. تہٕ تٔمۍ نِیوو میہ روحہٕ سٍتـ̡ أکِس بٔڈِس تہٕ تھدِ پہاڑس پیٹھ، تہٕ ہٲوُن میہ سُہ عظیم شہر، مقدس یروشلم، یُس خدایہ سٕندِ طرفہٕ آسمانہٕ پى۪ٹھٕ وسان چُھ،\n11.\\tخدایہ سُند جلال آسُن: تہٕ تٔمۍ سُند گاش اوس أکِس کٔنہِ ہیوٗ قیمتی پٲٹھۍ، یُس یۅسہٕ یۅسہٕ کُنہِ کُنہِ ہیوٗ یُس کرسٹل ہیوٗ صاف اوس۔\n12.\\tتہٕ اَکھ بٔڈ تہٕ تھوٚد دیوار، تہٕ دروازن پیٹھ ٲس باہ فرشتہٕ، تہٕ اتھ پیٹھ ٲسۍ ناو لیکھِتھ، یِم بنی اسرائیل کین بہن قبیلن ہٕندِ ناو چھِ:\n13.\\tمشرقس پیٹھ تریہ دروازہ۔ شمالس پیٹھ تریہ دروازٕ؛ جنوبس پیٹھ ترے دروازٕ؛ تہٕ مغربس پیٹھ ترے دروازٕ۔\n14.\\tتہٕ شہرٕچ دیوارس ٲس باہ بُنیاد تہٕ یِمن مَنٛز چھِ دامن ہٕندِس باہ رسولن ہٕندِ ناو۔\n15.\\tتہٕ یُس میہ سٍتـ̡ کتھ کٔرِتھ اوس، تس اوس شہرٕچ تہٕ اَمہ کِس دروازس تہٕ اَمہ کِس دیوارس ہُند پیمائش کرنہٕ خٲطرٕ اکھ سۄنہٕ نِلہٕ ۔\n16.\\tتہٕ شہر چُھ ژور مربعہٕ، تہٕ زیچھر چُھ کھجرس یوتاہ بوٚڈ آسان: تہٕ تٔمۍ پیمُت شہرس نِش باہ ساس فرلانگ سٍتـ̡ ۔ امیک زیچھر تہ کھجر تہ تھزر چھہ برابر۔\n17.\\tتہٕ تٔمۍ کٔر اَمہ کِس دیوارس ہتھ تہٕ ژتٲجی تہٕ ژور کیوبِٹ، {مطٲبق} انسان سُند پیمائش، یعنی فرشتہٕ سُند۔\n18.\\tتہٕ امچ دیوارچ تعمیر ٲس {of} جیسپر: تہٕ شہر اوس خالص سۄنہٕ، صاف شیشہٕ ہیو۔\n19.\\tتہٕ شہرٕچ دیوارٕچ بُنیاد آیہ پرٮ۪تھ قٕسمٕکۍ قیمتی کٔنو سٍتۍ سجاونہٕ۔ گوڑنچ بنیاد ٲس جیسپر۔ دوٚیِم، نیلم؛ تریم ، اکھ چالسیڈونی؛ ژورم، اکھ زمرد؛\n20. پونژم، سارڈونیکس؛ شیٚیِم، سارڈیئس؛ سٔتِم، کرسولائٹ؛ ٲٹھم، بیرل؛ نٔوِم، اکھ ٹوپاز؛ دٔہم، اکھ کرسوپراسس؛ کاہم، اکھ جیسنتھ؛ بٔہِم، اکھ امیتھیسٹ۔\n21. تہٕ باہ دروازٕ {ٲس} باہ موتی۔ پرٮ۪تھ واریاہ دروازٕ اوس أکِس موتُک تہٕ شہرٕچ سڑک ٲس خٲلص سۄنہٕ، تکیازِ یہٕ اوس شفاف شیشہٕ۔\n22. تہٕ میہ وُچھ نہٕ اَتھ مَنٛز کانہہ مندر: تکیازِ خداوند قادر مطلق تہٕ کۅکرِ چُھ اَمیُک مندر۔\n23.\\tتہٕ شہرس ٲس نہٕ آفتابٕچ تہٕ نہ زونہِ ہٕنز ضرورت، یُس اَتھ مَنٛز گاش دِنہٕ خٲطرٕ، تکیازِ خدایہ سٕندِ جلال سٍتـ̡ چُھ یہِ گاش دِژمُت، تہٕ کۅکرِ ہُند گاش چُھ۔\n24. تہٕ یِمن ہٕنزِ قومہٕ یِم نجات دِنہٕ آمٕژ چھِ، تِم گژھن اَمہِ کِس گاشس مَنٛز پَکُن: تہٕ زمینٕکۍ بادشاہ چھِ اَتھ مَنٛز پنٕنۍ شان تہٕ عزت انان۔\n25. تہٕ اَمہ کِس دروازٕ گژھِ نہٕ دۅہلہٕ بند کرنہٕ، تکیازِ تتہِ گژھہِ نہٕ رٲژ آسہِ۔\n26. تہٕ تِم انن قومن ہٕنز شان تہٕ عزت۔\n27.\\tتہٕ اتھ منز گژھہِ نہٕ کانہہ تہِ چیز دٲخل کرنہٕ یُس ناپاک آسہِ، نۂ کُنہِ تہِ کُنہِ","1. تہٕ تٔمۍ ہٲو مے زندگی ہُند اکھ پاک دریاو، یُس کرسٹل ہیوٗ صاف اوس، یُس خدایہ سٕندِ تہٕ کۅکرِ سٕندِس تختس پیٹھٕ نیران اوس۔\n2.\\tاَمہ کِس سڑکہِ منز، تہٕ دٔریاوٕ کِس دۅشوٕے اندۍ پکھۍ، اوس زندگی ہُند کُل، یُس باہ پھل اوس، {تہٕ} اوس پریتھ ریتہٕ پنن پھل دِوان: تہٕ کُلِکۍ پنہٕ ؤتھٕر ٲسۍ قومن ہٕندِ شفا خٲطرٕ۔\n3. تہٕ یێلہِ گژھہِ نہٕ کانہہ لعنت: مگر خدایہ سُند تہٕ کۅکرِ سُند تخت آسہِ اَتھ مَنٛز۔ تہٕ تٔمۍ سٕندِ خادم کٔرِن أمِس خدمت:\n4. تہٕ تِم وُچھن تٔمۍ سُند بُتھ۔ تہٕ تٔمۍ سُند ناو آسہِ تہندِس ڈیکس پیٹھ۔\n5. تہٕ تتہِ گژھہِ نہ کانہہ رات۔ تہٕ تِمن چھُنہٕ شَمبہِ ہٕنز ضرورت، نہ آفتابٕچ گاش۔ کیازِ خداوند خدا چُھ تِمن گاش دِوان، تہٕ تِم روزن ہمیشہٕ ہمیشہ خٲطرٕ بادشاہ۔\n6. تہٕ تٔمۍ ووٚن میہ زِ یِم کلام چھِ وفادار تہٕ صحیح: تہٕ خداوند پیغمبرن ہٕندِ خدایہ سُند فرشتہ سوز پننین بندن تِم چیز ہاونہٕ خٲطرٕ یِم جلدٕے گژھن گژھن۔\n7.\\tوُچھِو بہٕ جلدٕے یِوان: بابرکت چُھہ سُہ یُس امہِ کتابہِ ہٕنزِ پیشن گویی ہٕندِس قولس رٔٹِتھ چُھ۔\n8.\\tتہٕ میہ یوحنا وچھ یم چیز، تہٕ بوزمُت۔ تہٕ ییلہ میہ بوز تہٕ وُچھمُت، بہٕ پیوٚو فرشتہٕ سٕندِس قدمن برونہہ کُن عبادت کرنہٕ خٲطرٕ یٔمۍ مے یِم چیز ہٲوۍ۔\n9.\\tاَمہِ پَتہٕ چُھہ سُہ مےٚ وَنُن زِ وُچھِو نہٕ تُہُند سٲتھی تہٕ تُہٕندٮ۪ن باین مَنٛز پیغمبر، تہٕ یِم اتھ کتابہٕ ہٕندِس کلامَس مَنٛز تھاوان چھِ: خدایہ سٕنز عبادت کٔرِو۔\n10. تہٕ سُہ چُھ مےٚ ونان، یَتھ کتابہِ ہٕنزِ پیشن گویی ہٕندِس کَلامَس مُہر کٔرِو نہٕ: تِکیازِ وق چُھ یِوان۔\n11.\\tیُس بدکار آسہِ، سُہ گژھہِ بدکار روزُن، تہٕ یُس ناپاک آسہِ، سُہ گژھہِ وُنہِ تہِ گندٕ روزُن، تہٕ یُس پاک آسہِ، سُہ گژھہِ پاک روزُن۔\n12. تہٕ وُچھ، بہٕ چُھس جلدی یِوان۔ تہٕ میون انعامہٕ چُھہ میہ سٍتۍ، یُس پرٮ۪تھ أکِس انسانس تٔمۍ سٕنزِ کامہِ مُطٲبق دِنہٕ یُن۔\n13. بہٕ چھُس الفا تہٕ اومیگا، آغاز تہٕ اختتام، گۄڈنیُک تہٕ ٲخری ۔\n14. تِم چھِ تِم بابرکت یِم تٔمۍ سٕندِس حُکُم کٔرِتھ، یُتھ تِمن ہێکہِ زندگی ہٕندِس کُلِس پیٹھ حق حٲصِل سپدِتھ، تہٕ یِمن ہێکہِ دروازٕ کِنۍ شہرس مَنٛز اژِتھ۔\n15.\\tتکیازِ یُس محبت کرُن تہٕ اپُز کران چُھ، تہٕ یُس محبت کرِ، تہٕ اپُز کران چھُ۔\n16. بہٕ چُھس عیسیٰ مسیحن پنُن فرشتہ سوزمُت یُس کلیساہَن مَنٛز یِمن چیزن ہٕنز گوٲہی دِنہٕ خٲطرٕ۔ بہٕ چُھس داؤد سُند موٗل تہٕ اولاد، {تہٕ} چمکدار تہٕ صُبحُک ستارٕ۔\n17.\\tتہٕ روح تہٕ مہرِنۍ چھِ ونان یِمن ہُند وَنُن۔ تہٕ یُس بوزان چُھ، یُس بوزان چُھ، یُس وَنُن چُھ۔ تہٕ یُس پیاس آسہِ۔ تہٕ یُس تہِ یژھان چھُ، سُہ گژھہِ زندگی ہُند آب آزادانہٕ طور نِنہٕ۔\n18.\\tیِکیازِ بہٕ چُھس پرٮ۪تھ أکِس انسانس سٍتـ̡ گوٲہی دِوان یُس امہِ کتابہِ ہٕنزِ پیشن گویی ہٕندِس کلامس بوزان چُھ، یێلہِ کانہہ انسان یِمن چیزن مَنٛز اضافہٕ کرِ، تێلہِ کرِ خدایہ تٔمِس سٍتـ̡ یِم آفتہٕ یِم اتھ کتابہِ منز لیکھنہٕ آمٕتۍ چھِ:\n19. تہٕ یێلہِ کانہہ انسان امہِ پیشن گویی ہٕنزِ کتابہِ ہٕندِس کلامَس نِش ہٹاوِ، تہٕ یێلہِ کُنہِ کتابہِ مَنٛز لیکھنہٕ آمٕژ چُھہ تِمن چیزن نِش یُس اتھ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ۔ {کتابہ منز...: یا، زندگی ہندِ کُلِس منز}\n20.\\tیُس یُس یِمن چیزن ہٕنز گوٲہی دِوان چُھ، سُہ چُھہ ونان زِ بہٕ چُھس جلدی یِوان۔ آمین۔ توتہِ آو خداوند عیسیٰ۔\n21. سٲنـ̡ آغہٕ عیسیٰ مسیح سُند فضل {ہو} چُھہ تُہۍ سارِنٕے سٍتـ̡ سٍتـ̡ آمین۔"];
